  {
    path: "training/publish.py",
    content: "\"\"\"训练产物自动回传到 assets/——每轮训练结束自动调用，人只需 push。\n\n红线：只回传\"训练出来的能力\"，绝不回传数据（原图/原图路径/文章索引）。\n数据来源文件带 _local 后缀，被 gitignore，不会被收进来。\n\n收集映射（工作区产物 → assets/）：\n    training/models/structure_svc.joblib  → assets/classifier.joblib\n    training/templates/templates.json     → assets/templates.json\n    <root>/calibration.json               → assets/calibration.json\n    training/03-style/档位_*.json          → assets/style_profiles/档位_*.json\n\n用法：\n    python -m training.publish --root <工作区>\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport shutil\nfrom pathlib import Path\n\nASSETS = Path(__file__).resolve().parent.parent / \"assets\"\n\n\ndef _is_data(path: Path) -> bool:\n    \"\"\"红线判定：文件名带 _local 即数据明细，跳过。\"\"\"\n    return \"_local\" in path.name\n\n\ndef _copy_if_exists(src: Path, dst: Path, label: str) -> bool:\n    if not src.exists() or _is_data(src):\n        return False\n    dst.parent.mkdir(parents=True, exist_ok=True)\n    shutil.copy2(src, dst)\n    print(f\"  回传 {label}: {src.name} → {dst.relative_to(ASSETS.parent)}\")\n    return True\n\n\ndef publish(root: Path) -> dict:\n    root = Path(root).resolve()\n    t = root / \"training\"\n    copied = []\n\n    candidates = [\n        (t / \"models\" / \"structure_svc.joblib\", ASSETS / \"classifier.joblib\", \"分类器\"),\n        (t / \"templates\" / \"templates.json\", ASSETS / \"templates.json\", \"字符模板\"),\n        (root / \"calibration.json\", ASSETS / \"calibration.json\", \"校准参数\"),\n        (t / \"calibration.json\", ASSETS / \"calibration.json\", \"校准参数\"),\n    ]\n    for src, dst, label in candidates:\n        if _copy_if_exists(src, dst, label):\n            copied.append(label)\n\n    # 风格档位：只收纯参数档位 json，跳过 _local 明细\n    style_dir = t / \"03-style\"\n    if style_dir.exists():\n        for p in style_dir.glob(\"档位_*.json\"):\n            if _is_data(p):\n                continue\n            # 二次红线：内容里若有 members/image 字段，说明混了数据，剥掉再写\n            data = json.loads(p.read_text(encoding=\"utf-8\"))\n            data.pop(\"members\", None)\n            out = ASSETS / \"style_profiles\" / p.name\n            out.parent.mkdir(parents=True, exist_ok=True)\n            out.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding=\"utf-8\")\n            print(f\"  回传 风格档位: {p.name}（已确认无原图索引）\")\n            copied.append(f\"档位 {p.stem}\")\n\n    # 记录回传时间，便于确认是哪一轮\n    (ASSETS / \".last_publish.json\").write_text(\n        json.dumps({\"root\": str(root), \"items\": copied}, ensure_ascii=False, indent=2),\n        encoding=\"utf-8\")\n    print(f\"回传完成：{len(copied)} 项 → {ASSETS}（下一步：git commit + push）\")\n    return {\"items\": copied}\n\n\ndef main() -> None:\n    import argparse\n    ap = argparse.ArgumentParser(description=\"训练产物自动回传\")\n    ap.add_argument(\"--root\", required=True, help=\"工作区根目录\")\n    args = ap.parse_args()\n    publish(Path(args.root))\n\n\nif __name__ == \"__main__\":\n    main()\n",
  },
  {
    path: "training/sample_parallel.py",
    content: "\"\"\"并行按年代采样：每年抽多篇，多进程跑，用于统计\"画法的主流占比随年代推移\"。\n\n为什么需要并行与多篇：每年只抽 1 篇会抽到异常作者（实测 1950 年就有纯键线式），\n无法反映同期主流。每年代需要 5~10 篇才能在统计上站稳。\n\n用法：\n    python -m training.sample_parallel --pdfs <dir> --out <dir> --range 1900-1975 \\\n        --per-year 6 --pages 3 --workers 6\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport multiprocessing as mp\nfrom pathlib import Path\n\nfrom .style import year_from_filename\n\n\ndef _scan_one(args: tuple[str, int, int, int, str]) -> tuple[int, int, str]:\n    \"\"\"处理一篇 PDF：返回 (年份, 裁出张数, 文件名)。子进程内才 import 重库。\"\"\"\n    pdf_path, year, pages, dpi, out_dir = args\n    import cv2\n    import numpy as np\n    import pymupdf\n    from .detect import detect_page, load_model\n\n    model = load_model()\n    scale = dpi / 150.0\n    dst = Path(out_dir) / str(year)\n    dst.mkdir(parents=True, exist_ok=True)\n    n = 0\n    try:\n        doc = pymupdf.open(pdf_path)\n    except Exception:\n        return year, 0, Path(pdf_path).name\n    stem = Path(pdf_path).stem\n    for pg in range(min(pages, len(doc))):\n        try:\n            pinfo = detect_page(model, doc[pg], dpi=150)\n        except Exception:\n            continue\n        if not pinfo[\"boxes\"]:\n            continue\n        pix = doc[pg].get_pixmap(dpi=dpi)\n        arr = np.frombuffer(pix.samples, dtype=np.uint8).reshape(pix.height, pix.width, pix.n)\n        img = cv2.cvtColor(arr, cv2.COLOR_RGB2BGR) if pix.n >= 3 else arr\n        for box in pinfo[\"boxes\"]:\n            x1, y1, x2, y2 = (int(v * scale) for v in box[\"bbox\"])\n            pad = int(5 * scale)\n            crop = img[max(0, y1 - pad):min(img.shape[0], y2 + pad),\n                       max(0, x1 - pad):min(img.shape[1], x2 + pad)]\n            # 太小的是碎片/文字，不是结构式；留 40px 下限减少噪声\n            if crop.size == 0 or min(crop.shape[:2]) < 40:\n                continue\n            cv2.imwrite(str(dst / f\"{stem}_p{pg:03d}_f{n:02d}.png\"), crop)\n            n += 1\n    doc.close()\n    return year, n, Path(pdf_path).name\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(prog=\"csd-sample-parallel\")\n    ap.add_argument(\"--pdfs\", required=True)\n    ap.add_argument(\"--out\", required=True)\n    ap.add_argument(\"--range\", default=\"1900-1975\")\n    ap.add_argument(\"--per-year\", type=int, default=6)\n    ap.add_argument(\"--pages\", type=int, default=3)\n    ap.add_argument(\"--dpi\", type=int, default=300)\n    ap.add_argument(\"--workers\", type=int, default=6)\n    ap.add_argument(\"--max-crops\", type=int, default=10, help=\"每篇最多留几张（0=不限）\")\n    args = ap.parse_args()\n\n    lo, hi = (int(x) for x in args.range.split(\"-\"))\n    pdf_dir = Path(args.pdfs)\n    by_year: dict[int, list[Path]] = {}\n    for p in sorted(pdf_dir.glob(\"*.pdf\")):\n        y = year_from_filename(p.name)\n        if y and lo <= y <= hi:\n            by_year.setdefault(y, []).append(p)\n\n    tasks = []\n    for year in sorted(by_year):\n        for pdf in by_year[year][:args.per_year]:\n            tasks.append((str(pdf), year, args.pages, args.dpi, args.out))\n\n    total = 0\n    done = 0\n    with mp.Pool(args.workers) as pool:\n        for year, n, name in pool.imap_unordered(_scan_one, tasks, chunksize=1):\n            total += n\n            done += 1\n            if done % 20 == 0:\n                print(f\"  已处理 {done}/{len(tasks)} 篇，累计 {total} 张\", flush=True)\n    print(f\"完成：{done} 篇 → {total} 张，输出 {args.out}\")\n\n\nif __name__ == \"__main__\":\n    main()\n",
  },
  {
    path: "training/sample_quick.py",
    content: "\"\"\"快速采样：只取几个年代节点、少量页、少量图，用于验证\"画法随年代演化\"这条规律。\n\n与 sample_style.py 的区别：这个只要几十秒（每个年代 1 篇 × 前 2 页 × 最多 5 张），\n够用来确认特征是否单调，跑全量再用 sample_style。\n\n用法：\n    python -m training.sample_quick --pdfs <dir> --out <dir> --years 1900,1920,1940,1955,1965,1972\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nfrom pathlib import Path\n\nfrom .detect import detect_page, load_model\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(prog=\"csd-sample-quick\")\n    ap.add_argument(\"--pdfs\", required=True)\n    ap.add_argument(\"--out\", required=True)\n    ap.add_argument(\"--years\", default=\"1900,1920,1940,1955,1965,1972\")\n    ap.add_argument(\"--max-crops\", type=int, default=5)\n    ap.add_argument(\"--pages\", type=int, default=2)\n    ap.add_argument(\"--dpi\", type=int, default=300)\n    args = ap.parse_args()\n\n    import cv2\n    import numpy as np\n    import pymupdf\n\n    pdf_dir = Path(args.pdfs)\n    out_root = Path(args.out)\n    years = [int(y) for y in args.years.split(\",\")]\n    model = load_model()\n\n    for year in years:\n        cand = sorted(p for p in pdf_dir.glob(\"*.pdf\") if p.name.startswith(str(year)))\n        if not cand:\n            print(f\"{year}: 无文件\", flush=True)\n            continue\n        pdf = cand[0]\n        dst = out_root / str(year)\n        dst.mkdir(parents=True, exist_ok=True)\n        n = 0\n        try:\n            doc = pymupdf.open(pdf)\n        except Exception as exc:\n            print(f\"{year}: 打不开 {exc}\", flush=True)\n            continue\n        scale = args.dpi / 150.0\n        for pg in range(min(args.pages, len(doc))):\n            pinfo = detect_page(model, doc[pg], dpi=150)\n            if not pinfo[\"boxes\"]:\n                continue\n            pix = doc[pg].get_pixmap(dpi=args.dpi)\n            arr = np.frombuffer(pix.samples, dtype=np.uint8).reshape(pix.height, pix.width, pix.n)\n            img = cv2.cvtColor(arr, cv2.COLOR_RGB2BGR) if pix.n >= 3 else arr\n            for box in pinfo[\"boxes\"]:\n                if n >= args.max_crops:\n                    break\n                x1, y1, x2, y2 = (int(v * scale) for v in box[\"bbox\"])\n                pad = int(6 * scale)\n                crop = img[max(0, y1 - pad):min(img.shape[0], y2 + pad),\n                           max(0, x1 - pad):min(img.shape[1], x2 + pad)]\n                if crop.size == 0 or min(crop.shape[:2]) < 24:\n                    continue\n                cv2.imwrite(str(dst / f\"{year}_p{pg:03d}_f{n:02d}.png\"), crop)\n                n += 1\n        doc.close()\n        print(f\"{year}: {n} 张  ({pdf.name})\", flush=True)\n\n\nif __name__ == \"__main__\":\n    main()\n",
  },
  {
    path: "training/sample_style.py",
    content: "\"\"\"采样：按年代分层，从 PDF 里裁出真实结构式图，供记法分类器验证/校准。\n\n为什么必须采样：分类器要能证明\"画法随年代单调演化\"，不能只在一两篇上看着像。\n年份从文件名取（用户已标注年份在文件名里）。\n\n用法：\n    python -m training.sample_style --pdfs <目录> --out <目录> --per-year 6 --years 1900-1980\n产物：\n    <out>/<year>/<pdfstem>_p<PAGE>_f<i>.png   每个年代一个文件夹\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nfrom pathlib import Path\n\nfrom .detect import detect_page, load_model\nfrom .style import year_from_filename\n\n\ndef _pdfs_by_year(pdf_dir: Path) -> dict[int, list[Path]]:\n    out: dict[int, list[Path]] = {}\n    for p in sorted(pdf_dir.glob(\"*.pdf\")):\n        y = year_from_filename(p.name)\n        if y is None:\n            continue\n        out.setdefault(y, []).append(p)\n    return out\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(prog=\"csd-sample-style\")\n    ap.add_argument(\"--pdfs\", required=True, help=\"PDF 目录\")\n    ap.add_argument(\"--out\", required=True, help=\"输出目录（按年份分文件夹）\")\n    ap.add_argument(\"--per-year\", type=int, default=6, help=\"每年最多采多少篇\")\n    ap.add_argument(\"--years\", default=\"1900-1980\", help=\"年份范围 a-b\")\n    ap.add_argument(\"--max-crops\", type=int, default=8, help=\"每篇最多留几张图\")\n    ap.add_argument(\"--dpi\", type=int, default=300, help=\"裁图 dpi（300 是环检测可用的下限）\")\n    args = ap.parse_args()\n\n    lo, hi = (int(x) for x in args.years.split(\"-\"))\n    pdf_dir = Path(args.pdfs)\n    out_root = Path(args.out)\n    by_year = _pdfs_by_year(pdf_dir)\n\n    import cv2\n    import numpy as np\n    import pymupdf\n\n    model = load_model()\n    total = 0\n    for year in sorted(y for y in by_year if lo <= y <= hi):\n        picked = by_year[year][:args.per_year]\n        dst = out_root / str(year)\n        dst.mkdir(parents=True, exist_ok=True)\n        n = 0\n        for pdf in picked:\n            if n >= args.max_crops:\n                break\n            try:\n                doc = pymupdf.open(pdf)\n            except Exception:\n                continue\n            for pinfo in (detect_page(model, page, dpi=args.dpi) for page in doc):\n                if n >= args.max_crops:\n                    break\n                if not pinfo[\"boxes\"]:\n                    continue\n                # 用 150dpi 坐标系做 detect，裁图用 300dpi → 坐标乘 2\n                scale = args.dpi / 150.0\n                pix = doc[pinfo[\"page\"] - 1].get_pixmap(dpi=args.dpi)\n                arr = np.frombuffer(pix.samples, dtype=np.uint8).reshape(pix.height, pix.width, pix.n)\n                img = cv2.cvtColor(arr, cv2.COLOR_RGB2BGR) if pix.n >= 3 else arr\n                for box in pinfo[\"boxes\"]:\n                    if n >= args.max_crops:\n                        break\n                    x1, y1, x2, y2 = (int(v * scale) for v in box[\"bbox\"])\n                    pad = int(6 * scale)\n                    crop = img[max(0, y1 - pad):min(img.shape[0], y2 + pad),\n                               max(0, x1 - pad):min(img.shape[1], x2 + pad)]\n                    if crop.size == 0 or crop.shape[0] < 24 or crop.shape[1] < 24:\n                        continue\n                    name = f\"{pdf.stem}_p{pinfo['page']:03d}_f{n:02d}.png\"\n                    cv2.imwrite(str(dst / name), crop)\n                    n += 1\n                    total += 1\n            doc.close()\n        print(f\"{year}: {n} 张\", flush=True)\n    print(f\"共 {total} 张，输出 {out_root}\")\n\n\nif __name__ == \"__main__\":\n    main()\n",
  },
  {
    path: "training/sample_yearly.py",
    content: "\"\"\"每年抽一篇，看实际有几种画法（不预设档位数）。\n\n用户指示：不一定是三个档位，每年抽一篇跑小量，自己看有多少种风格。\n所以这里只采样 + 出特征，**不做任何档位假设**，交给聚类去发现自然簇数。\n\n用法：\n    python -m training.sample_yearly --pdfs <dir> --out <dir> --range 1900-1975\n产物：<out>/<year>/<year>_p<page>_f<i>.png\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nfrom pathlib import Path\n\nfrom .detect import detect_page, load_model\nfrom .style import year_from_filename\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(prog=\"csd-sample-yearly\")\n    ap.add_argument(\"--pdfs\", required=True)\n    ap.add_argument(\"--out\", required=True)\n    ap.add_argument(\"--range\", default=\"1900-1975\")\n    ap.add_argument(\"--per-year\", type=int, default=1, help=\"每年抽几篇\")\n    ap.add_argument(\"--max-crops\", type=int, default=4, help=\"每篇最多留几张\")\n    ap.add_argument(\"--pages\", type=int, default=2, help=\"每篇扫前几页\")\n    ap.add_argument(\"--dpi\", type=int, default=300)\n    args = ap.parse_args()\n\n    import cv2\n    import numpy as np\n    import pymupdf\n\n    lo, hi = (int(x) for x in args.range.split(\"-\"))\n    pdf_dir = Path(args.pdfs)\n    out_root = Path(args.out)\n\n    by_year: dict[int, list[Path]] = {}\n    for p in sorted(pdf_dir.glob(\"*.pdf\")):\n        y = year_from_filename(p.name)\n        if y and lo <= y <= hi:\n            by_year.setdefault(y, []).append(p)\n\n    model = load_model()\n    scale = args.dpi / 150.0\n    total = 0\n    for year in sorted(by_year):\n        for pdf in by_year[year][:args.per_year]:\n            dst = out_root / str(year)\n            dst.mkdir(parents=True, exist_ok=True)\n            n = 0\n            try:\n                doc = pymupdf.open(pdf)\n            except Exception:\n                continue\n            for pg in range(min(args.pages, len(doc))):\n                if n >= args.max_crops:\n                    break\n                pinfo = detect_page(model, doc[pg], dpi=150)\n                if not pinfo[\"boxes\"]:\n                    continue\n                pix = doc[pg].get_pixmap(dpi=args.dpi)\n                arr = np.frombuffer(pix.samples, dtype=np.uint8).reshape(pix.height, pix.width, pix.n)\n                img = cv2.cvtColor(arr, cv2.COLOR_RGB2BGR) if pix.n >= 3 else arr\n                for box in pinfo[\"boxes\"]:\n                    if n >= args.max_crops:\n                        break\n                    x1, y1, x2, y2 = (int(v * scale) for v in box[\"bbox\"])\n                    pad = int(6 * scale)\n                    crop = img[max(0, y1 - pad):min(img.shape[0], y2 + pad),\n                               max(0, x1 - pad):min(img.shape[1], x2 + pad)]\n                    if crop.size == 0 or min(crop.shape[:2]) < 28:\n                        continue\n                    cv2.imwrite(str(dst / f\"{year}_p{pg:03d}_f{n:02d}.png\"), crop)\n                    n += 1\n                    total += 1\n            doc.close()\n        print(f\"{year}: 累计 {total} 张\", flush=True)\n    print(f\"完成，共 {total} 张\")\n\n\nif __name__ == \"__main__\":\n    main()\n",
  },
  {
    path: "training/style.py",
    content: "\"\"\"训练②④：风格聚类定档（约束聚类）→ 参数化仿古渲染。\n\n② 风格识别：主分类器是聚类，人的标注只作初筛种子（must-link / cannot-link）。\n年份是强特征（DOI / 文件名已知），参与聚类并用于验证同档一致性。\n档位数量由数据决定，不预设年代档；只考虑 1985 年前的画风。\n\n④ 仿古渲染：RDKit MolDraw2DCairo 参数化 + 取代基库。\nRDKit 无法逐片段设置渲染参数，segment_styles 仅作接口预留并显式警告。\n\n可单独调试：\n    python -m training.style cluster --images <dir> --out <dir>\n    python -m training.style eval --profiles <_cluster_detail_local.json> --truth <truth.json>\n    python -m training.style render --smiles <smi> --style <style.json> --out <png>\n    python -m training.style batch --style-dir <dir> --out <dir> --smiles \"<smi>\" ...\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport json\nimport random\nimport re\nimport warnings\nfrom collections import Counter, defaultdict\nfrom dataclasses import asdict, dataclass, field, is_dataclass\nfrom pathlib import Path\n\nimport numpy as np\n\ntry:\n    import cv2\nexcept ImportError:  # 允许模块先于图像依赖可用；extract_features 调用时再明确报错\n    cv2 = None\n\nYEAR_WEIGHT = 1.5          # 年份是强特征，标准化后加权\nMAX_AUTO_CLUSTERS = 8      # 无种子时层次聚类最多保留的档位数\nIMAGE_EXTS = (\".png\", \".jpg\", \".jpeg\")\n\n\ndef _pick_font_path() -> str:\n    \"\"\"按平台探测衬线字体；都找不到就留空，走 RDKit 默认字体。\"\"\"\n    import platform\n    candidates = [\n        r\"C:\\Windows\\Fonts\\times.ttf\",\n        \"/System/Library/Fonts/Times Roman.ttf\",\n        \"/usr/share/fonts/truetype/dejavu/DejaVuSerif.ttf\",\n    ]\n    for p in candidates:\n        if Path(p).exists():\n            return p\n    return \"\"\n\n\nDEFAULT_FONT_PATH = _pick_font_path()\n\n\n# --------------------------------------------------------------------------\n# 数据结构（均可用 dataclasses.asdict 转 dict → json 序列化）\n# --------------------------------------------------------------------------\n@dataclass\nclass StyleFeatures:\n    image: str\n    stroke_width: float\n    ink_density: float\n    aspect: float\n    has_circle_aromatic: int\n    year: int | None = None\n    year_missing: bool = False\n\n    FEATURE_NAMES = (\"stroke_width\", \"ink_density\", \"aspect\", \"has_circle_aromatic\", \"year\")\n\n    def vector(self) -> list[float]:\n        y = 0.0 if self.year is None else float(self.year)\n        return [float(self.stroke_width), float(self.ink_density),\n                float(self.aspect), float(self.has_circle_aromatic), y]\n\n    def to_dict(self) -> dict:\n        d = asdict(self)\n        d[\"feature_names\"] = list(self.FEATURE_NAMES)\n        d[\"vector\"] = self.vector()\n        return d\n\n\n@dataclass\nclass StyleProfile:\n    \"\"\"一个画风档位。前 7 个字段与原版一致，保证 pipeline.py 的 StyleProfile(**json) 可用。\"\"\"\n    name: str\n    stroke_width: float\n    font_size: float\n    bond_length: float\n    mono: bool\n    sample_count: int = 0\n    note: str = \"\"\n    # 扩展字段（约束聚类 / 评估 / 渲染所需，均有默认值以兼容旧 json）\n    line_width: float = 0.0\n    font_path: str = DEFAULT_FONT_PATH\n    seed_label: str = \"\"                                  # 对应人的标注档位名\n    centroid: list[float] = field(default_factory=list)   # 标准化空间中的簇中心\n    members: list[dict] = field(default_factory=list)     # [{image, year, vector}]\n    year_median: float | None = None\n    year_span: int = 0\n\n    def to_dict(self) -> dict:\n        return asdict(self)\n\n    def to_json(self) -> str:\n        return json.dumps(self.to_dict(), ensure_ascii=False, indent=2)\n\n\n# --------------------------------------------------------------------------\n# ② 风格识别\n# --------------------------------------------------------------------------\ndef year_from_filename(name: str) -> int | None:\n    \"\"\"从 'ABRAHAMSON1948_xxx.pdf' / 'xxx_1948.pdf' 提取年份，无则 None。\"\"\"\n    m = re.search(r\"(?<!\\d)(1[8-9]\\d{2}|20[0-2]\\d)(?!\\d)\", str(name))\n    if not m:\n        return None\n    year = int(m.group(1))\n    return year if 1800 <= year <= 2029 else None\n\n\ndef _runs(values: np.ndarray) -> list[tuple[int, int]]:\n    if len(values) == 0:\n        return []\n    out, start, prev = [], int(values[0]), int(values[0])\n    for v in values[1:]:\n        v = int(v)\n        if v == prev + 1:\n            prev = v\n        else:\n            out.append((start, prev))\n            start = prev = v\n    out.append((start, prev))\n    return out\n\n\ndef extract_features(image_path: str | Path, year: int | None = None) -> dict:\n    \"\"\"提取可聚类的画风特征；返回 dict，含 vector 与 feature_names。\"\"\"\n    if cv2 is None:\n        raise RuntimeError(\"需要 opencv-python-headless 才能提取图像特征（pip install -r requirements.txt）\")\n    img = cv2.imread(str(image_path), cv2.IMREAD_GRAYSCALE)\n    if img is None:\n        raise ValueError(f\"读不了图片: {image_path}\")\n    h, w = img.shape\n    _, binary = cv2.threshold(img, 0, 255, cv2.THRESH_BINARY_INV + cv2.THRESH_OTSU)\n    ink = binary > 0\n    density = float(ink.mean())\n\n    # 线宽 = 单行内水平墨迹段的宽度中位数（不是整列跨度——那会把整个分子宽度当线宽）\n    widths = []\n    for row in ink:\n        cols = np.where(row)[0]\n        for start, end in _runs(cols):\n            widths.append(end - start + 1)\n    stroke = float(np.median(widths)) if widths else 1.0\n\n    try:\n        circles = cv2.HoughCircles(img, cv2.HOUGH_GRADIENT, dp=1.2, minDist=18,\n                                   param1=100, param2=22, minRadius=8, maxRadius=70)\n    except cv2.error:\n        circles = None\n\n    if year is None:\n        year = year_from_filename(Path(image_path).name)\n    feat = StyleFeatures(\n        image=str(image_path),\n        stroke_width=round(stroke, 3),\n        ink_density=round(density, 4),\n        aspect=round(w / max(h, 1), 3),\n        has_circle_aromatic=1 if circles is not None else 0,\n        year=year,\n        year_missing=year is None,\n    )\n    return feat.to_dict()\n\n\ndef _as_dict(obj) -> dict:\n    if is_dataclass(obj) and not isinstance(obj, type):\n        return asdict(obj)\n    if isinstance(obj, dict):\n        return dict(obj)\n    raise TypeError(f\"需要 dict 或 dataclass，收到 {type(obj).__name__}\")\n\n\ndef _matrix(features: list[dict]) -> tuple[np.ndarray, np.ndarray, int]:\n    \"\"\"构造原始矩阵、标准化矩阵（年份加权、缺失填中位数），返回 (raw, x, year_col)。\"\"\"\n    rows = [_as_dict(f) for f in features]\n    names = rows[0].get(\"feature_names\", list(StyleFeatures.FEATURE_NAMES))\n    year_col = names.index(\"year\") if \"year\" in names else len(names) - 1\n    raw = np.array([f.get(\"vector\") or [f[n] for n in names] for f in rows], dtype=float)\n\n    years = np.array([r.get(\"year\") if r.get(\"year\") else np.nan for r in rows], dtype=float)\n    if not np.all(np.isnan(years)):\n        years = np.where(np.isnan(years), float(np.nanmedian(years)), years)\n    else:\n        years = np.full(len(rows), 1900.0)\n    raw[:, year_col] = years\n\n    x = raw.copy()\n    std = x.std(axis=0)\n    std[std < 1e-9] = 1.0\n    x = (x - x.mean(axis=0)) / std\n    x[:, year_col] *= YEAR_WEIGHT\n    return raw, x, year_col\n\n\ndef _auto_labels(x: np.ndarray) -> np.ndarray:\n    \"\"\"无种子：ward 层次聚类按距离自动定档，限制最多 MAX_AUTO_CLUSTERS。\"\"\"\n    n = len(x)\n    if n <= 1:\n        return np.ones(n, dtype=int)\n    try:\n        from scipy.cluster.hierarchy import fcluster, linkage\n    except ImportError:  # 无 scipy 时退化为按笔画/圈标记分箱\n        warnings.warn(\"scipy 不可用，退化为笔画/圈标记分箱（档位较粗糙）。\", UserWarning)\n        return np.clip((x[:, 0] > 0).astype(int) + (x[:, 3] > 0).astype(int), 0, 3) + 1\n\n    z = linkage(x, method=\"ward\")\n    cap = max(2, min(MAX_AUTO_CLUSTERS, max(2, n // 2)))\n    threshold = 1.5\n    labels = fcluster(z, t=threshold, criterion=\"distance\")\n    for _ in range(8):\n        if len(np.unique(labels)) <= cap:\n            break\n        threshold *= 1.35\n        labels = fcluster(z, t=threshold, criterion=\"distance\")\n    return labels.astype(int)\n\n\ndef _seeded_labels(x: np.ndarray, seed_pairs: list[tuple[int, str]]) -> tuple[np.ndarray, np.ndarray]:\n    \"\"\"约束聚类：人的标注作种子，同标签 must-link / 异标签 cannot-link。\n\n    种子样本固定归属其标注档位并作为初始中心，其余样本按距离归入；\n    迭代重算中心直到收敛。返回 (labels, centers)。\n    \"\"\"\n    n = len(x)\n    names = sorted({label for _, label in seed_pairs})\n    index = {name: j for j, name in enumerate(names)}\n    k = len(names)\n    centers = np.array([x[[i for i, lab in seed_pairs if lab == name]].mean(axis=0)\n                        for name in names], dtype=float)\n\n    labels = np.full(n, -1, dtype=int)\n    for i, lab in seed_pairs:\n        labels[i] = index[lab]\n\n    for _ in range(100):\n        for i in range(n):\n            if labels[i] < 0:\n                labels[i] = int(np.argmin(((x[i] - centers) ** 2).sum(axis=1)))\n        new_centers = centers.copy()\n        for j in range(k):\n            mask = labels == j\n            if mask.any():\n                new_centers[j] = x[mask].mean(axis=0)\n        if np.allclose(new_centers, centers):\n            break\n        centers = new_centers\n    return labels, centers\n\n\ndef cluster_styles(features: list[dict], out_dir, seed_labels: dict | None = None) -> list[dict]:\n    \"\"\"聚类定档。seed_labels: {image_path: '档位A'} 人的标注作种子。\n\n    返回 list[dict]（可 json 序列化）；写出每档 <档位_*.json> 及\n    _cluster_detail_local.json（含 members，供 evaluate_clusters 使用）。\n    \"\"\"\n    out_dir = Path(out_dir)\n    out_dir.mkdir(parents=True, exist_ok=True)\n    if not features:\n        warnings.warn(\"② 没有图像特征可聚类：features 为空（数据尚未到位？）\")\n        return []\n\n    rows = [_as_dict(f) for f in features]\n    raw, x, year_col = _matrix(rows)\n    n = len(rows)\n\n    seed_pairs: list[tuple[int, str]] = []\n    if seed_labels:\n        for i, f in enumerate(rows):\n            image = str(f.get(\"image\", \"\"))\n            label = seed_labels.get(image)\n            if label is None:\n                label = seed_labels.get(Path(image).name)\n            if label is not None:\n                seed_pairs.append((i, str(label)))\n\n    centers = None\n    if seed_pairs:\n        labels, centers = _seeded_labels(x, seed_pairs)\n    else:\n        labels = _auto_labels(x)\n\n    groups: dict[int, list[int]] = defaultdict(list)\n    for i, lab in enumerate(labels):\n        groups[int(lab)].append(i)\n\n    profiles: list[dict] = []\n    for order, lab in enumerate(sorted(groups), start=1):\n        idxs = groups[lab]\n        members = []\n        for i in idxs:\n            f = rows[i]\n            members.append({\n                \"image\": str(f.get(\"image\", \"\")),\n                \"year\": f.get(\"year\"),\n                \"vector\": [float(v) for v in raw[i]],\n            })\n        years = [m[\"year\"] for m in members if m[\"year\"]]\n        med = np.median(raw[idxs], axis=0)\n        seed_names = sorted({seed_labels.get(str(rows[i].get(\"image\", \"\")))\n                             or seed_labels.get(Path(str(rows[i].get(\"image\", \"\"))).name)\n                             for i in idxs} - {None}) if seed_pairs else []\n        stroke = float(med[0])\n        profile = StyleProfile(\n            name=f\"档位 {order}\",\n            stroke_width=round(stroke, 3),\n            font_size=14.0,\n            bond_length=-1.0,\n            mono=True,\n            sample_count=len(idxs),\n            note=\"由约束聚类得出，非预设年代档\" if seed_pairs else \"由聚类得出，非预设年代档\",\n            line_width=round(stroke, 3),\n            seed_label=\"/\".join(seed_names),\n            centroid=[float(v) for v in (centers[lab] if centers is not None\n                                         else x[idxs].mean(axis=0))],\n            members=[],  # 成员明细含原图路径=数据，单独写本地 _cluster_detail_local.json，不进 assets\n            year_median=float(np.median(years)) if years else None,\n            year_span=int(max(years) - min(years)) if years else 0,\n        )\n        data = profile.to_dict()\n        profiles.append(data)\n        (out_dir / f\"档位_{order}.json\").write_text(\n            json.dumps(data, ensure_ascii=False, indent=2), encoding=\"utf-8\")\n\n    # 明细含 members（每篇原图路径+向量）= 数据，写 _local 后缀文件（gitignore），不进 assets 交付\n    local_detail = {\n        \"feature_names\": list(rows[0].get(\"feature_names\", StyleFeatures.FEATURE_NAMES)),\n        \"year_weight\": YEAR_WEIGHT,\n        \"has_seed\": bool(seed_pairs),\n        \"profiles\": profiles,\n        \"members_by_profile\": [\n            [{\"image\": str(rows[i].get(\"image\", \"\")),\n              \"year\": rows[i].get(\"year\"),\n              \"vector\": [float(v) for v in raw[i]]}\n             for i in groups[lab]]\n            for lab in sorted(groups)\n        ],\n    }\n    (out_dir / \"_cluster_detail_local.json\").write_text(\n        json.dumps(local_detail, ensure_ascii=False, indent=2), encoding=\"utf-8\")\n    return profiles\n\n\ndef _find_truth(image: str, truth: dict):\n    if image in truth:\n        return truth[image]\n    base = Path(image).name\n    if base in truth:\n        return truth[base]\n    for key, value in truth.items():\n        if Path(str(key)).name == base:\n            return value\n    return None\n\n\ndef evaluate_clusters(profiles, truth: dict, members_by_profile=None) -> dict:\n    \"\"\"训练/测试准确度 + silhouette + 同档一致性。\n\n    profiles: cluster_styles 的返回（list[dict] 或 list[StyleProfile]）。\n    truth: {image_path: '档位A'} 人的标注真值。\n    members_by_profile: _cluster_detail_local.json 里的成员明细（按 profile 顺序）。\n      成员含原图路径=数据，不能进 assets，所以 profile[\"members\"] 被置空，\n      评估时必须用这里的副本，否则永远只有 0 个样本。\n    \"\"\"\n    result: dict = {\"accuracy\": None, \"n_train\": 0, \"n_test\": 0,\n                    \"silhouette\": None, \"cluster_purity\": None,\n                    \"year_consistency\": [], \"per_cluster\": [], \"warnings\": []}\n    if not truth:\n        result[\"warnings\"].append(\"没有 truth 标注，无法评估准确度。\")\n        return result\n\n    profiles = [p if isinstance(p, dict) else asdict(p) for p in (profiles or [])]\n    samples = []\n    for cid, prof in enumerate(profiles):\n        members = prof.get(\"members\") or []\n        if not members and members_by_profile and cid < len(members_by_profile):\n            members = members_by_profile[cid] or []\n        for m in members:\n            label = _find_truth(str(m.get(\"image\", \"\")), truth)\n            if label is not None and m.get(\"vector\"):\n                samples.append((str(m[\"image\"]), m.get(\"year\"), np.array(m[\"vector\"], float),\n                                cid, label))\n    if len(samples) < 2:\n        result[\"warnings\"].append(f\"只有 {len(samples)} 个可对照样本，至少需要 2 个。\")\n        return result\n\n    x = np.array([s[2] for s in samples], dtype=float)\n    std = x.std(axis=0)\n    std[std < 1e-9] = 1.0\n    x = (x - x.mean(axis=0)) / std\n    labels = [s[4] for s in samples]\n    classes = sorted(set(labels))\n\n    rng = random.Random(42)\n    idx_by_label: dict[str, list[int]] = defaultdict(list)\n    for i, lab in enumerate(labels):\n        idx_by_label[lab].append(i)\n    train_idx, test_idx = [], []\n    for lab in classes:\n        idxs = idx_by_label[lab]\n        rng.shuffle(idxs)\n        if len(idxs) >= 2:\n            n_test = min(max(1, round(len(idxs) * 0.2)), len(idxs) - 1)\n            test_idx.extend(idxs[:n_test])\n            train_idx.extend(idxs[n_test:])\n        else:\n            train_idx.extend(idxs)\n            result[\"warnings\"].append(f\"档位 '{lab}' 只有 1 个样本，仅用于训练。\")\n\n    result[\"n_train\"], result[\"n_test\"] = len(train_idx), len(test_idx)\n    if test_idx:\n        centers = {lab: x[[i for i in train_idx if labels[i] == lab]].mean(axis=0)\n                   for lab in classes if any(labels[i] == lab for i in train_idx)}\n        preds = [min(centers, key=lambda lab: float(((x[i] - centers[lab]) ** 2).sum()))\n                 for i in test_idx]\n        actual = [labels[i] for i in test_idx]\n        result[\"accuracy\"] = round(sum(p == a for p, a in zip(preds, actual)) / len(actual), 4)\n    else:\n        result[\"warnings\"].append(\"没有测试样本，无法计算准确度。\")\n\n    if len(classes) >= 2 and len(samples) >= 3:\n        try:\n            from sklearn.metrics import silhouette_score\n            result[\"silhouette\"] = round(float(silhouette_score(x, labels)), 4)\n        except (ImportError, ValueError) as exc:\n            result[\"warnings\"].append(f\"silhouette 不可用: {exc}\")\n\n    # 同档一致性：每个聚类簇里 truth 众数占比；年份跨度作辅助验证信号\n    correct = total = 0\n    for cid, prof in enumerate(profiles):\n        rows = [s for s in samples if s[3] == cid]\n        if not rows:\n            continue\n        counts = Counter(s[4] for s in rows)\n        correct += max(counts.values())\n        total += len(rows)\n        years = [s[1] for s in rows if s[1]]\n        result[\"per_cluster\"].append({\n            \"cluster\": prof.get(\"name\"),\n            \"n\": len(rows),\n            \"dominant_label\": counts.most_common(1)[0][0],\n            \"purity\": round(max(counts.values()) / len(rows), 4),\n            \"year_span\": int(max(years) - min(years)) if years else None,\n        })\n        if years:\n            result[\"year_consistency\"].append({\"cluster\": prof.get(\"name\"),\n                                               \"span\": int(max(years) - min(years))})\n    result[\"cluster_purity\"] = round(correct / total, 4) if total else None\n    return result\n\n\n# --------------------------------------------------------------------------\n# ④ 仿古渲染\n# --------------------------------------------------------------------------\ndef _render_params(style) -> dict:\n    d = _as_dict(style)\n\n    def pick(*keys, default):\n        for key in keys:\n            if d.get(key) is not None:\n                return d[key]\n        return default\n\n    return {\n        \"line_width\": float(pick(\"line_width\", \"stroke_width\", default=1.0)),\n        \"font_size\": float(pick(\"font_size\", default=14.0)),\n        \"bond_length\": float(pick(\"bond_length\", \"fixed_bond_length\", default=-1.0)),\n        \"mono\": bool(pick(\"mono\", \"useBWAtomPalette\", default=True)),\n        \"font_path\": str(pick(\"font_path\", default=DEFAULT_FONT_PATH)),\n    }\n\n\ndef render_cache_key(smiles: str, style, segment_styles: dict | None = None) -> str:\n    \"\"\"仅依据真正影响渲染的参数做 sha256，避免 members 变动导致缓存失效。\"\"\"\n    payload = {\"version\": 1, \"smiles\": smiles, \"params\": _render_params(style),\n               \"segment_styles\": segment_styles or {}}\n    blob = json.dumps(payload, sort_keys=True, ensure_ascii=False, separators=(\",\", \":\"))\n    return hashlib.sha256(blob.encode(\"utf-8\")).hexdigest()[:16]\n\n\ndef render_smiles(smiles: str, style, out_png, segment_styles: dict | None = None) -> None:\n    \"\"\"参数化渲染单分子。style 可为 dict 或 StyleProfile（兼容 pipeline.py）。\n\n    segment_styles 仅作接口预留：RDKit 不支持对主链/侧链分别设线宽字体，\n    传入非空值时显式警告，绝不假装做到了分段画法。\n    \"\"\"\n    if segment_styles:\n        warnings.warn(\n            \"segment_styles 已接收但被忽略：RDKit MolDraw2DCairo 不支持对主链/侧链\"\n            \"分别设置线宽/字体/键长；整个分子将使用同一套参数（未实现分段画法）。\",\n            UserWarning, stacklevel=2)\n    params = _render_params(style)\n    try:\n        from rdkit import Chem\n        from rdkit.Chem import Draw, rdDepictor\n    except ImportError as exc:\n        raise RuntimeError(\"需要 RDKit：pip install rdkit（仿古渲染依赖它）\") from exc\n\n    mol = Chem.MolFromSmiles(smiles)\n    if mol is None:\n        raise ValueError(f\"非法 SMILES: {smiles}\")\n    rdDepictor.Compute2DCoords(mol)\n\n    opts = Draw.MolDrawOptions()\n    # RDKit 新版属性名：bondLineWidth / fixedFontSize（旧版 lineWidth/fontSize 已废弃）\n    for name in (\"bondLineWidth\", \"lineWidth\"):\n        if hasattr(opts, name):\n            setattr(opts, name, float(params[\"line_width\"]))\n            break\n    for name in (\"fixedFontSize\", \"fontSize\"):\n        if hasattr(opts, name):\n            setattr(opts, name, int(params[\"font_size\"]))\n            break\n    if params[\"bond_length\"] > 0:\n        opts.fixedBondLength = int(params[\"bond_length\"])\n    if params[\"mono\"] and hasattr(opts, \"useBWAtomPalette\"):\n        opts.useBWAtomPalette()\n    font_path = Path(params[\"font_path\"])\n    if params[\"font_path\"] and font_path.exists():\n        try:\n            opts.fontFile = str(font_path)\n        except Exception as exc:  # 版本差异时退回默认字体\n            warnings.warn(f\"无法设置字体 {font_path}: {exc}\", UserWarning)\n\n    drawer = Draw.MolDraw2DCairo(600, 400)\n    drawer.SetDrawOptions(opts)\n    drawer.DrawMolecule(mol)\n    drawer.FinishDrawing()\n\n    out_png = Path(out_png)\n    out_png.parent.mkdir(parents=True, exist_ok=True)\n    out_png.write_bytes(drawer.GetDrawingText())\n\n\ndef _load_substituents_safe() -> dict:\n    \"\"\"取代基库由另一模块提供；模块暂不存在时降级为空，不中断渲染。\"\"\"\n    load = None\n    for module in (\"training.substituents\", \".substituents\"):\n        try:\n            if module.startswith(\".\"):\n                from importlib import import_module\n                load = getattr(import_module(module, __package__), \"load_substituents\")\n            else:\n                from training.substituents import load_substituents as load\n            break\n        except (ImportError, AttributeError):\n            continue\n    if load is None:\n        warnings.warn(\"training.substituents 尚不可用，跳过取代基库渲染。\", UserWarning)\n        return {}\n    try:\n        return load() or {}\n    except Exception as exc:\n        warnings.warn(f\"load_substituents 调用失败，跳过取代基库: {exc}\", UserWarning)\n        return {}\n\n\ndef render_batch(smiles_list: list[str], style_dir, out_dir, cache_dir=None) -> list[dict]:\n    \"\"\"按所有档位批量渲染（含共享取代基库），命中缓存则复用 PNG。\"\"\"\n    style_dir, out_dir = Path(style_dir), Path(out_dir)\n    out_dir.mkdir(parents=True, exist_ok=True)\n    cache_dir = Path(cache_dir) if cache_dir else out_dir / \"_cache\"\n    cache_dir.mkdir(parents=True, exist_ok=True)\n\n    styles = []\n    for path in sorted(style_dir.glob(\"*.json\")):\n        if path.name.startswith(\"_\"):\n            continue\n        try:\n            data = json.loads(path.read_text(encoding=\"utf-8\"))\n            if isinstance(data, dict) and \"name\" in data:\n                styles.append((path.stem, data))\n        except (ValueError, OSError) as exc:\n            warnings.warn(f\"跳过无效风格档 {path.name}: {exc}\", UserWarning)\n    if not styles:\n        warnings.warn(f\"④ 风格档目录没有可用 json：{style_dir}（先跑 cluster）\")\n        return []\n\n    smiles = list(dict.fromkeys(s for s in smiles_list if s))\n    substituents = _load_substituents_safe()\n    for item in substituents.values():\n        s = item.get(\"smiles\") if isinstance(item, dict) else getattr(item, \"smiles\", None)\n        if s:\n            smiles.append(s)\n    smiles = list(dict.fromkeys(smiles))\n    if not smiles:\n        warnings.warn(\"render_batch 没有任何 SMILES 可渲染。\")\n        return []\n\n    results = []\n    for smi in smiles:\n        for stem, style in styles:\n            key = render_cache_key(smi, style)\n            cached = cache_dir / f\"{key}.png\"\n            hit = cached.exists()\n            if not hit:\n                try:\n                    render_smiles(smi, style, cached)\n                except (ValueError, RuntimeError) as exc:\n                    warnings.warn(f\"渲染失败 {smi} / {stem}: {exc}\", UserWarning)\n                    continue\n            target = out_dir / f\"{stem}_{key[:8]}.png\"\n            if not target.exists():\n                target.write_bytes(cached.read_bytes())\n            results.append({\"smiles\": smi, \"style\": style.get(\"name\", stem),\n                            \"png\": str(target), \"cache_key\": key, \"cache_hit\": hit})\n    return results\n\n\n# --------------------------------------------------------------------------\n# CLI\n# --------------------------------------------------------------------------\ndef _read_json(path: str):\n    return json.loads(Path(path).read_text(encoding=\"utf-8\"))\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(description=\"训练②④：风格聚类 / 评估 / 仿古渲染\")\n    sub = ap.add_subparsers(dest=\"cmd\", required=True)\n\n    c = sub.add_parser(\"cluster\", help=\"② 约束聚类定档\")\n    c.add_argument(\"--images\", required=True)\n    c.add_argument(\"--out\", default=\"data/training/styles\")\n    c.add_argument(\"--seed-labels\", help=\"人的标注 json: {image_path: '档位A'}\")\n\n    e = sub.add_parser(\"eval\", help=\"训练/测试准确度与同档一致性\")\n    e.add_argument(\"--profiles\", required=True, help=\"cluster 输出的 _cluster_detail_local.json（含成员明细）\")\n    e.add_argument(\"--truth\", required=True, help=\"人的标注 json\")\n\n    r = sub.add_parser(\"render\", help=\"④ 渲染单个分子\")\n    r.add_argument(\"--smiles\", required=True)\n    r.add_argument(\"--style\", required=True)\n    r.add_argument(\"--out\", required=True)\n    r.add_argument(\"--segment-styles\", help=\"预留的分段画法参数 json（当前会被忽略并警告）\")\n\n    b = sub.add_parser(\"batch\", help=\"④ 批量渲染（含取代基库 + 缓存）\")\n    b.add_argument(\"--smiles\", nargs=\"*\", default=[])\n    b.add_argument(\"--style-dir\", required=True)\n    b.add_argument(\"--out\", required=True)\n    b.add_argument(\"--cache-dir\")\n\n    args = ap.parse_args()\n\n    if args.cmd == \"cluster\":\n        images = [p for p in Path(args.images).rglob(\"*\") if p.suffix.lower() in IMAGE_EXTS]\n        if not images:\n            print(f\"⚠ 没有图片：{args.images}（数据尚未到位？）\")\n            return\n        seeds = _read_json(args.seed_labels) if args.seed_labels else None\n        feats = [extract_features(p) for p in images]\n        profiles = cluster_styles(feats, Path(args.out), seed_labels=seeds)\n        print(f\"从 {len(feats)} 张图聚出 {len(profiles)} 档（种子={'是' if seeds else '否'}）→ {args.out}\")\n        for p in profiles:\n            print(f\"  {p['name']}: stroke={p['stroke_width']} samples={p['sample_count']} \"\n                  f\"year_span={p['year_span']} seed={p['seed_label'] or '-'}\")\n    elif args.cmd == \"eval\":\n        detail = _read_json(args.profiles)\n        profiles = detail[\"profiles\"] if isinstance(detail, dict) and \"profiles\" in detail else detail\n        members = detail.get(\"members_by_profile\") if isinstance(detail, dict) else None\n        metrics = evaluate_clusters(profiles, _read_json(args.truth), members)\n        print(json.dumps(metrics, ensure_ascii=False, indent=2))\n    elif args.cmd == \"render\":\n        segments = _read_json(args.segment_styles) if args.segment_styles else None\n        render_smiles(args.smiles, _read_json(args.style), Path(args.out), segment_styles=segments)\n        print(f\"渲染到 {args.out}\")\n    else:\n        results = render_batch(args.smiles, args.style_dir, args.out, args.cache_dir)\n        hits = sum(1 for r in results if r[\"cache_hit\"])\n        print(f\"渲染 {len(results)} 张（缓存命中 {hits}）→ {args.out}\")\n\n\nif __name__ == \"__main__\":\n    main()\n",
  },
  {
    path: "training/style_spectrum.py",
    content: "\"\"\"看风格谱：按年份打印每张图的\"显式碳程度\"分数与关键特征，判断是连续谱还是离散簇。\n\n为什么先做这个而不是直接聚类：用户要求\"看有多少种风格\"。若分数随年代**连续渐变**，\n则\"档位\"只是人为切段（早期/中期/晚期），而不是数据里的天然簇；\n若出现明显**双峰/多峰**，才说明真有并行画派，需要多档。\n\n用法：python -m training.style_spectrum --dir <按年份目录>\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport statistics\nfrom collections import defaultdict\nfrom pathlib import Path\n\nfrom .notation import FEATURE_NAMES, describe, extract_notation\nfrom .notation_clf import density_score\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(prog=\"csd-style-spectrum\")\n    ap.add_argument(\"--dir\", required=True)\n    ap.add_argument(\"--step\", type=int, default=10, help=\"每多少年汇总一行\")\n    args = ap.parse_args()\n\n    root = Path(args.dir)\n    rows = []\n    for d in sorted(root.iterdir()):\n        if not d.is_dir() or not d.name.isdigit():\n            continue\n        year = int(d.name)\n        for p in sorted(d.iterdir()):\n            if p.suffix.lower() not in (\".png\", \".jpg\", \".jpeg\"):\n                continue\n            try:\n                f = extract_notation(p)\n            except Exception:\n                continue\n            v = dict(zip(FEATURE_NAMES, f.values))\n            rows.append({\"year\": year, \"score\": density_score(f), \"name\": p.name,\n                         \"ink\": v[\"text_ink_fraction\"], \"wide\": v[\"group_wideness\"],\n                         \"pb\": v[\"group_per_bond\"], \"tier\": describe(f)[\"tier\"]})\n\n    if not rows:\n        raise SystemExit(\"没有样本\")\n\n    print(f\"总样本 {len(rows)} 张，年份 {min(r['year'] for r in rows)}~{max(r['year'] for r in rows)}\")\n    print()\n    print(f\"{'年段':>10} {'n':>3} {'score均值':>9} {'ink':>6} {'wide':>6} {'pb':>6}\")\n    buckets: dict[int, list[dict]] = defaultdict(list)\n    for r in rows:\n        buckets[(r[\"year\"] // args.step) * args.step].append(r)\n    for b in sorted(buckets):\n        rs = buckets[b]\n        sc = [r[\"score\"] for r in rs]\n        print(f\"{b:>4}-{b+args.step-1:<5} {len(rs):>3} {statistics.mean(sc):>9.3f} \"\n              f\"{statistics.mean([r['ink'] for r in rs]):>6.2f} \"\n              f\"{statistics.mean([r['wide'] for r in rs]):>6.2f} \"\n              f\"{statistics.mean([r['pb'] for r in rs]):>6.2f}\")\n\n    # 分数分布：是单峰渐变还是多峰（多峰=真有多画派）\n    scores = sorted(r[\"score\"] for r in rows)\n    print()\n    print(\"分数分布直方（10 桶，看是单峰还是多峰）：\")\n    lo, hi = scores[0], scores[-1]\n    span = max(hi - lo, 1e-6)\n    hist = [0] * 10\n    for s in scores:\n        hist[min(9, int((s - lo) / span * 10))] += 1\n    peak = max(hist)\n    for i, h in enumerate(hist):\n        bar = \"#\" * int(60 * h / peak) if peak else \"\"\n        print(f\"  {lo + span*i/10:5.2f}~{lo + span*(i+1)/10:5.2f} | {h:>3} {bar}\")\n\n    # 关键：三档占比随年代推移——风格是同期并存的，主流占比才会迁移。\n    # 所以判定标准不是\"每年只有一种风格\"，而是\"占比重心逐年移动\"。\n    print()\n    print(\"按年段的三档占比（显式碳程度高→低）：\")\n    print(f\"{'年段':>10} {'n':>3} {'高显式%':>8} {'中混合%':>8} {'纯键线%':>8}\")\n    hi_t, lo_t = 0.62, 0.34\n    for b in sorted(buckets):\n        rs = buckets[b]\n        hh = sum(1 for r in rs if r[\"score\"] >= hi_t) / len(rs) * 100\n        mm = sum(1 for r in rs if lo_t <= r[\"score\"] < hi_t) / len(rs) * 100\n        ll = sum(1 for r in rs if r[\"score\"] < lo_t) / len(rs) * 100\n        print(f\"{b:>4}-{b+args.step-1:<5} {len(rs):>3} {hh:>8.1f} {mm:>8.1f} {ll:>8.1f}\")\n\n\nif __name__ == \"__main__\":\n    main()\n",
  },
  {
    path: "training/substituent_delta.py",
    content: "\"\"\"取代基拓扑增幅：从 substituents 库查 SMILES → RDKit 真算指标。\n\n用户 2026-11-26：\"去库里查 SMILES，再把 SMILES 给 RDKit，用 RDKit 把指标增幅算出来。\"\n不再手填 ring_sizes/hetero。指标口径与 layer1_graph 一致。\n\"\"\"\nfrom __future__ import annotations\n\ntry:\n    from .substituents import SUBSTITUENTS\n    from .layer1_graph import truth_from_rdkit, ring_systems\nexcept ImportError:\n    from substituents import SUBSTITUENTS\n    from layer1_graph import truth_from_rdkit, ring_systems\n\nfrom rdkit import Chem\n\n\ndef delta_from_smiles(smiles: str) -> dict | None:\n    \"\"\"从 SMILES 用 RDKit 算取代基自身的六个拓扑指标。\"\"\"\n    mol = Chem.MolFromSmiles(smiles)\n    if mol is None:\n        return None\n    t = truth_from_rdkit(mol)\n    hetero = sorted({a.GetSymbol() for a in mol.GetAtoms()\n                     if a.GetSymbol() not in (\"C\", \"H\", \"*\")})\n    rings = [set(r) for r in mol.GetRingInfo().AtomRings()]\n    systems = ring_systems(rings) if rings else []\n    sizes = t[\"ring_sizes\"]\n    return {\n        \"smiles\": smiles,\n        \"ring_sizes\": sizes,\n        \"hetero\": hetero,\n        \"has_ring\": len(rings) > 0,\n        \"has_multi_ring\": len(rings) >= 2,\n        \"has_fused_fragment\": any(len(s) >= 2 for s in systems),\n        # 非稠环片段 = 存在孤立单环（Ph 自身即满足）\n        \"has_disconnected_fragment\": any(len(s) == 1 for s in systems),\n        \"small_ring\": any(3 <= s <= 4 for s in sizes),\n        \"big_ring\": any(s >= 7 for s in sizes),\n        \"n_v\": mol.GetNumAtoms(), \"n_e\": mol.GetNumBonds(),\n    }\n\n\ndef delta_of(notation: str) -> dict | None:\n    \"\"\"按缩写查库取 SMILES，再用 RDKit 算增幅。\"\"\"\n    e = SUBSTITUENTS.get(notation)\n    return delta_from_smiles(e[\"smiles\"]) if e else None\n\n\nif __name__ == \"__main__\":\n    print(f\"{'缩写':<8} {'SMILES':<20} {'环':<12} {'杂原子':<12} {'多稠碎':<6}\")\n    for name, e in SUBSTITUENTS.items():\n        d = delta_from_smiles(e[\"smiles\"])\n        if not d:\n            print(f\"{name:<8} SMILES 无法解析\")\n            continue\n        flags = (int(d[\"has_multi_ring\"]), int(d[\"has_fused_fragment\"]),\n                 int(d[\"has_disconnected_fragment\"]))\n        print(f\"{name:<8} {e['smiles']:<20} {str(d['ring_sizes']):<12} \"\n              f\"{','.join(d['hetero']):<12} {flags[0]}{flags[1]}{flags[2]}\")\n",
  },
  {
    path: "training/substituent_topology.py",
    content: "\"\"\"取代基拓扑增量库：识别到某个图上缩写后，拓扑指标怎么变。\n\n与 training/substituents.py 的分工（不覆盖、不混用）：\n  - substituents.py 管\"风格渲染/文字匹配\"：字段 hetero/ring/smiles\n  - 本库管\"拓扑指标增量\"：识别到缩写 → 六个存在性指标各自怎么变\n\n用户口径（2026-11-26）：\n  - 取代基库不是跨时代归一化，同一个符号恒代表同一含义。\n  - 只收\"图和字对不上\"的缩写（Me/Ph/SO3H...）；显式 CH3 所见即所得不进库。\n  - 取代基是压缩包(ZIP)：图上写 Me，实际是 CH3；不解压就会漏拓扑指标。\n  - 输出的是存在性层面的改变，不是精确计数（对齐\"只判有无\"原则）。\n\n六个指标（与 layer1_graph.py 一致）：\n  has_ring, has_multi_ring, has_fused_fragment, has_disconnected_fragment,\n  small_ring(3/4), big_ring(>=7), heteroatoms(类型)\n  中环(5/6) 靠排除法，不直接给。\n\n每条规则字段：\n  notation      图上写法\n  expanded      展开代表\n  ring_sizes    展开带来的环大小列表（Ph→[6]，非连通环）\n  hetero        展开带来的杂原子类型 set（N/O/S/P/卤素/Si...）\n  adds_ring     是否新增环 → 触发 has_ring\n  ring_conn     新环的连接方式：'isolated'(非连通,自身成一片) / 'none'\n                —— 自身单环缩写都算自身一片；不可能与主环稠合（距离上连不上）\n  注：一个缩写自身带 ≥2 环且共享原子(如萘系缩写)才触发 fused，本库暂无此类。\n\"\"\"\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\n\n\n@dataclass(frozen=True)\nclass Delta:\n    \"\"\"一个取代基对拓扑指标的增量。\"\"\"\n    notation: str\n    expanded: str\n    ring_sizes: tuple[int, ...] = ()\n    hetero: tuple[str, ...] = ()\n    adds_ring: bool = False\n    # 缩写自身带来的环是否彼此连成一片（≥2 环且共享原子才可能 fused）\n    self_fused: bool = False\n    # 出处：wiki=ChemInform/Wikipedia 伪元素表；html=有机化学教材；chemist=常见化学常识\n    source: str = \"\"\n\n    @property\n    def contributes_multi(self) -> bool:\n        \"\"\"这个展开式自身是否贡献\"多环\"（≥2 个环）。\"\"\"\n        return len(self.ring_sizes) >= 2\n\n    @property\n    def contributes_disconnected(self) -> bool:\n        \"\"\"这个展开式自身是否贡献\"非稠环片段\"（≥2 个彼此不连通的环系）。\"\"\"\n        # 单环缩写接到主结构上：它自己是一片环系。若主结构已有环系，则整体\n        # 变成 ≥2 个环系 → 非稠环片段。这个判定在合成层做（要看主结构）。\n        # 这里只标记\"该缩写自带一个独立环系\"。\n        return len(self.ring_sizes) == 1\n\n\ndef _d(notation, expanded, ring_sizes=(), hetero=(), self_fused=False, source=\"wiki\"):\n    return Delta(\n        notation=notation,\n        expanded=expanded,\n        ring_sizes=tuple(ring_sizes),\n        hetero=tuple(sorted(set(hetero))),\n        adds_ring=bool(ring_sizes),\n        self_fused=self_fused,\n        source=source,\n    )\n\n\n# 只收\"图和字对不上\"的缩写。显式 CH3/C2H5 等所见即所得，不进库。\n# 出处：\n#   wiki    = Wikipedia \"Skeletal formula\" + Wikiwand \"Chemical symbol\" 的伪元素表\n#   cheminfo= Wiley《ChemInform》官方缩写表（Abbreviations used in ChemInform）\n#   common  = 有机化学通用官能团/保护基写法（教材常见，未逐条引上表）\nLIBRARY: dict[str, Delta] = {d.notation: d for d in [\n    # —— 烷基 / 通用基（无环、无杂原子）—— wiki\n    _d(\"Me\",   \"CH3\",          source=\"wiki\"),\n    _d(\"Et\",   \"C2H5\",         source=\"wiki\"),\n    _d(\"Pr\",   \"C3H7\",         source=\"wiki\"),\n    _d(\"n-Pr\", \"CH2CH2CH3\",    source=\"wiki\"),\n    _d(\"i-Pr\", \"CH(CH3)2\",     source=\"wiki\"),\n    _d(\"Bu\",   \"C4H9\",         source=\"wiki\"),\n    _d(\"n-Bu\", \"CH2CH2CH2CH3\", source=\"wiki\"),\n    _d(\"i-Bu\", \"CH2CH(CH3)2\",  source=\"wiki\"),\n    _d(\"s-Bu\", \"CH(CH3)CH2CH3\",source=\"wiki\"),\n    _d(\"t-Bu\", \"C(CH3)3\",      source=\"wiki\"),\n    _d(\"Pn\",   \"C5H11\",        source=\"wiki\"),\n    _d(\"Am\",   \"C5H11\",        source=\"wiki\"),\n    _d(\"Hx\",   \"C6H13\",        source=\"ipfs\"),\n    _d(\"Hp\",   \"C7H15\",        source=\"ipfs\"),\n    _d(\"Np\",   \"CH2C(CH3)3\",   source=\"wiki\"),          # new=新戊基；有机金属里也指 neophyl\n    _d(\"Neo\",  \"CH2C(CH3)3\",   source=\"wiki\"),\n    _d(\"Nph\",  \"C(CH3)2C6H5\",  source=\"wiki\"),          # neophyl，带苯环\n    _d(\"Ad\",   \"1-金刚烷基\",    source=\"wiki\"),\n    _d(\"Vi\",   \"CH=CH2\",       source=\"wiki\"),\n    _d(\"All\",  \"CH2CH=CH2\",    source=\"wiki\"),\n    _d(\"R\",    \"通式烷基\",      source=\"wiki\"),\n    _d(\"R'\",   \"通式烷基(变体1)\", source=\"common\"),\n    _d(\"R''\",  \"通式烷基(变体2)\", source=\"common\"),\n    _d(\"Alk\",  \"通式烷基\",      source=\"wiki\"),\n    _d(\"Het\",  \"通式杂芳基\",    source=\"wiki\", hetero=[\"N\", \"O\", \"S\"]),\n    _d(\"E\",    \"通式亲电基\",    source=\"wiki\"),\n    _d(\"Nu\",   \"通式亲核基\",    source=\"wiki\"),\n    _d(\"Ar\",   \"通式芳基\",      source=\"wiki\"),\n    _d(\"Alk\",  \"通式烷基\",      source=\"ipfs\"),\n    _d(\"X\",    \"通式卤素\",      source=\"wiki\", hetero=[\"F\", \"Cl\", \"Br\", \"I\"]),\n    _d(\"D\",    \"氘(2H)\",        source=\"ipfs\"),\n    _d(\"T\",    \"氚(3H)\",        source=\"ipfs\"),\n\n    # —— 芳香基（带非连通环）—— wiki\n    _d(\"Ph\",  \"C6H5\",          ring_sizes=[6], source=\"wiki\"),\n    _d(\"Φ\",   \"C6H5\",          ring_sizes=[6], source=\"wiki\"),\n    _d(\"Tol\", \"CH3C6H4\",       ring_sizes=[6], source=\"wiki\"),\n    _d(\"Mes\", \"(CH3)3C6H2\",    ring_sizes=[6], source=\"wiki\"),\n    _d(\"Cp\",  \"C5H5\",          ring_sizes=[5], source=\"wiki\"),\n    _d(\"Cp*\", \"C5(CH3)5\",      ring_sizes=[5], source=\"wiki\"),\n    _d(\"Cyp\", \"C5H9\",          ring_sizes=[5], source=\"wiki\"),\n    _d(\"Cy\",  \"C6H11\",         ring_sizes=[6], source=\"wiki\"),\n    _d(\"Chx\", \"C6H11\",         ring_sizes=[6], source=\"ipfs\"),\n    _d(\"Bn\",  \"CH2C6H5\",       ring_sizes=[6], source=\"wiki\"),\n    _d(\"Bzl\", \"CH2C6H5\",       ring_sizes=[6], source=\"ipfs\"),\n    _d(\"Tr\",  \"C(C6H5)3\",      ring_sizes=[6, 6, 6], source=\"wiki\"),\n    _d(\"Trt\", \"C(C6H5)3\",      ring_sizes=[6, 6, 6], source=\"wiki\"),\n    _d(\"φ\",   \"C6H5\",          ring_sizes=[6], source=\"wiki\"),\n    _d(\"An\",  \"p-CH3OC6H4\",   ring_sizes=[6], hetero=[\"O\"], source=\"wiki\"),\n    _d(\"Dipp\",\"2,6-(iPr)2C6H3\", ring_sizes=[6], source=\"wiki\"),\n    _d(\"Is\",  \"2,4,6-(iPr)3C6H2\", ring_sizes=[6], source=\"wiki\"),\n    _d(\"Tipp\",\"2,4,6-(iPr)3C6H2\", ring_sizes=[6], source=\"wiki\"),\n\n    # —— 酰基 / 含氧官能团（无环）—— cheminfo / common\n    _d(\"Ac\",   \"COCH3\",        hetero=[\"O\"], source=\"cheminfo\"),\n    _d(\"Bz\",   \"COC6H5\",       ring_sizes=[6], hetero=[\"O\"], source=\"cheminfo\"),\n    _d(\"Piv\",  \"COC(CH3)3\",    hetero=[\"O\"], source=\"wiki\"),\n    _d(\"CHO\",  \"CHO\",          hetero=[\"O\"], source=\"common\"),\n    _d(\"CO2H\", \"COOH\",         hetero=[\"O\"], source=\"common\"),\n    _d(\"CO2R\", \"COOR\",         hetero=[\"O\"], source=\"common\"),\n    _d(\"CONH2\",\"CONH2\",        hetero=[\"N\", \"O\"], source=\"common\"),\n    _d(\"Bt\",   \"1-苯并三唑基\",  ring_sizes=[6], hetero=[\"N\"], source=\"wiki\"),\n    _d(\"Im\",   \"1-咪唑基\",      ring_sizes=[5], hetero=[\"N\"], source=\"wiki\"),\n    _d(\"NPhth\",\"邻苯二甲酰亚胺基\", ring_sizes=[6], hetero=[\"N\", \"O\"], source=\"wiki\"),\n    _d(\"OMe\",  \"OCH3\",         hetero=[\"O\"], source=\"cheminfo\"),\n    _d(\"OEt\",  \"OC2H5\",        hetero=[\"O\"], source=\"cheminfo\"),\n    _d(\"OH\",   \"OH\",           hetero=[\"O\"], source=\"common\"),\n\n    # —— 含氮 —— common\n    _d(\"NH2\",  \"NH2\",          hetero=[\"N\"], source=\"common\"),\n    _d(\"NMe2\", \"N(CH3)2\",      hetero=[\"N\"], source=\"common\"),\n    _d(\"NEt2\", \"N(C2H5)2\",     hetero=[\"N\"], source=\"common\"),\n    _d(\"NHMe\", \"NHCH3\",        hetero=[\"N\"], source=\"common\"),\n    _d(\"CN\",   \"CN\",           hetero=[\"N\"], source=\"common\"),\n    _d(\"NC\",   \"N=C\",          hetero=[\"N\"], source=\"common\"),\n    _d(\"NO2\",  \"NO2\",          hetero=[\"N\", \"O\"], source=\"common\"),\n    _d(\"NO\",   \"NO\",           hetero=[\"N\", \"O\"], source=\"common\"),\n    _d(\"N3\",   \"N3\",           hetero=[\"N\"], source=\"common\"),\n\n    # —— 含硫 / 磺酰基 —— wiki / cheminfo\n    _d(\"SO3H\", \"SO3H\",         hetero=[\"S\", \"O\"], source=\"common\"),\n    _d(\"SO2R\", \"SO2R\",         hetero=[\"S\", \"O\"], source=\"common\"),\n    _d(\"SR\",   \"SR\",           hetero=[\"S\"], source=\"common\"),\n    _d(\"Ms\",   \"SO2CH3\",       hetero=[\"S\", \"O\"], source=\"wiki\"),\n    _d(\"Tf\",   \"SO2CF3\",       hetero=[\"S\", \"O\", \"F\"], source=\"wiki\"),\n    _d(\"Ts\",   \"p-CH3C6H4SO2\", ring_sizes=[6], hetero=[\"S\", \"O\"], source=\"wiki\"),\n    _d(\"Tos\",  \"p-CH3C6H4SO2\", ring_sizes=[6], hetero=[\"S\", \"O\"], source=\"wiki\"),\n    _d(\"Bs\",   \"p-BrC6H4SO2\",  ring_sizes=[6], hetero=[\"S\", \"O\", \"Br\"], source=\"wiki\"),\n    _d(\"Ns\",   \"p-NO2C6H4SO2\", ring_sizes=[6], hetero=[\"N\", \"O\", \"S\"], source=\"wiki\"),\n    _d(\"Nf\",   \"CF3(CF2)3SO2\", hetero=[\"F\", \"S\", \"O\"], source=\"wiki\"),\n    _d(\"PhSO2\",\"SO2C6H5\",      ring_sizes=[6], hetero=[\"S\", \"O\"], source=\"common\"),\n    # —— 离去基（含氧磺酸酯，wiki 明确列出）——\n    _d(\"OBz\",  \"OCOC6H5\",      ring_sizes=[6], hetero=[\"O\"], source=\"wiki\"),\n    _d(\"OPiv\", \"OCOC(CH3)3\",   hetero=[\"O\"], source=\"wiki\"),\n    _d(\"OBs\",  \"OSO2C6H4Br\",   ring_sizes=[6], hetero=[\"O\", \"S\", \"Br\"], source=\"wiki\"),\n    _d(\"OMs\",  \"OSO2CH3\",      hetero=[\"O\", \"S\"], source=\"wiki\"),\n    _d(\"ONs\",  \"OSO2C6H4NO2\",  ring_sizes=[6], hetero=[\"O\", \"S\", \"N\"], source=\"wiki\"),\n    _d(\"OTf\",  \"OSO2CF3\",      hetero=[\"O\", \"S\", \"F\"], source=\"wiki\"),\n    _d(\"ONf\",  \"OSO2(CF2)3CF3\", hetero=[\"O\", \"S\", \"F\"], source=\"wiki\"),\n    _d(\"OTs\",  \"OSO2C6H4CH3\",  ring_sizes=[6], hetero=[\"O\", \"S\"], source=\"wiki\"),\n\n    # —— 含卤素 / 硅 —— common / cheminfo\n    _d(\"CF3\",  \"CF3\",          hetero=[\"F\"], source=\"common\"),\n    _d(\"CCl3\", \"CCl3\",         hetero=[\"Cl\"], source=\"common\"),\n    _d(\"TMS\",  \"Si(CH3)3\",     hetero=[\"Si\"], source=\"cheminfo\"),\n    _d(\"Tbs\",  \"Si(CH3)2C(CH3)3\", hetero=[\"Si\"], source=\"cheminfo\"),\n    _d(\"Tes\",  \"Si(C2H5)3\",    hetero=[\"Si\"], source=\"cheminfo\"),\n    _d(\"Tips\", \"Si(CH(CH3)2)3\", hetero=[\"Si\"], source=\"cheminfo\"),\n    _d(\"Sem\",  \"CH2OCH2CH2Si(CH3)3\", hetero=[\"O\", \"Si\"], source=\"cheminfo\"),\n\n    # —— 保护基（cheminfo 明确列出）——\n    _d(\"Boc\",  \"COOC(CH3)3\",   hetero=[\"O\"], source=\"cheminfo\"),\n    _d(\"Cbz\",  \"COOCH2C6H5\",   ring_sizes=[6], hetero=[\"O\"], source=\"cheminfo\"),\n    _d(\"Z\",    \"COOCH2C6H5\",   ring_sizes=[6], hetero=[\"O\"], source=\"wiki\"),\n    _d(\"Cbo\",  \"COOCH2C6H5\",   ring_sizes=[6], hetero=[\"O\"], source=\"ipfs\"),\n    _d(\"Fmoc\", \"COOCH2-芴\",     ring_sizes=[6, 6], hetero=[\"O\"], source=\"cheminfo\"),\n    _d(\"Alloc\",\"COOCH2CH=CH2\", hetero=[\"O\"], source=\"common\"),\n    _d(\"Mom\",  \"CH2OCH3\",      hetero=[\"O\"], source=\"cheminfo\"),\n    _d(\"Mem\",  \"CH2OCH2CH2OCH3\", hetero=[\"O\"], source=\"cheminfo\"),\n    _d(\"EE\",   \"OCH(CH3)OC2H5\", hetero=[\"O\"], source=\"cheminfo\"),\n    _d(\"Pmb\",  \"p-CH3OC6H4CH2\", ring_sizes=[6], hetero=[\"O\"], source=\"cheminfo\"),\n    _d(\"Dmt\",  \"4,4'-二甲氧基三苯甲基\", ring_sizes=[6, 6, 6], hetero=[\"O\"], source=\"cheminfo\"),\n    _d(\"Troc\", \"COOCH2CCl3\",   hetero=[\"O\", \"Cl\"], source=\"cheminfo\"),\n    _d(\"PMB\",  \"p-CH3OC6H4CH2\", ring_sizes=[6], hetero=[\"O\"], source=\"wiki\"),\n    _d(\"MOM\",  \"CH2OCH3\",      hetero=[\"O\"], source=\"wiki\"),\n    _d(\"THP\",  \"2-四氢吡喃基\",  ring_sizes=[6], hetero=[\"O\"], source=\"wiki\"),\n    _d(\"TBDMS\",\"Si(CH3)2C(CH3)3\", hetero=[\"Si\"], source=\"wiki\"),\n    _d(\"TBDPS\",\"Si(C6H5)2C(CH3)3\", ring_sizes=[6, 6], hetero=[\"Si\"], source=\"wiki\"),\n]}\n\n\ndef delta_of(notation: str) -> Delta | None:\n    \"\"\"按图上写法取增量。大小写不敏感，去下标/上标数字已由调用方 normalize。\"\"\"\n    if notation in LIBRARY:\n        return LIBRARY[notation]\n    low = notation.lower()\n    for name, d in LIBRARY.items():\n        if name.lower() == low:\n            return d\n    return None\n\n\ndef apply_deltas(base: dict, notations: list[str]) -> dict:\n    \"\"\"把一组识别到的取代基增量合成到 base 指标上（存在性 OR）。\n\n    base 形如：\n      {has_ring, has_multi_ring, has_fused_fragment,\n       has_disconnected_fragment, ring_sizes:[...], heteroatoms:[...]}\n    规则：\n      - 每个带环缩写贡献一个独立环系 → 整体环系计数 +1\n      - 存在只有 1 个环的孤立环系 → has_disconnected_fragment=True（Ph 自身即满足）\n      - 环数 ≥2 → has_multi_ring=True\n      - 任一环 3/4 → small_ring；任一 ≥7 → big_ring\n      - 杂原子类型取并集\n    \"\"\"\n    out = dict(base)\n    ring_sizes = list(base.get(\"ring_sizes\", []))\n    hetero = set(base.get(\"heteroatoms\", []))\n    n_systems = int(base.get(\"n_ring_systems\", 1 if ring_sizes else 0))\n    # 是否存在孤立单环（非稠环片段）：Ph 自身即满足\n    has_isolated = bool(base.get(\"has_disconnected_fragment\"))\n\n    for notation in notations:\n        d = delta_of(notation)\n        if d is None:\n            continue\n        ring_sizes.extend(d.ring_sizes)\n        hetero.update(d.hetero)\n        if d.ring_sizes:\n            # 缩写带来的环系数：自身 fused 的算一片，其余每个环各一片\n            # （如 Tr 三苯甲基 = 3 个苯环 = 3 个互不连通的环系）\n            n_systems += 1 if d.self_fused else len(d.ring_sizes)\n            # 非自身 fused 的单环缩写贡献一个孤立单环\n            if not d.self_fused and len(d.ring_sizes) == 1:\n                has_isolated = True\n\n    out[\"ring_sizes\"] = sorted(ring_sizes)\n    out[\"heteroatoms\"] = sorted(hetero)\n    out[\"has_ring\"] = bool(ring_sizes) or bool(base.get(\"has_ring\"))\n    out[\"has_multi_ring\"] = len(ring_sizes) >= 2 or bool(base.get(\"has_multi_ring\"))\n    out[\"has_fused_fragment\"] = bool(base.get(\"has_fused_fragment\"))\n    out[\"has_disconnected_fragment\"] = has_isolated\n    out[\"n_ring_systems\"] = n_systems\n    any_small = any(3 <= s <= 4 for s in ring_sizes)\n    any_big = any(s >= 7 for s in ring_sizes)\n    out[\"small_ring\"] = any_small or bool(base.get(\"small_ring\"))\n    out[\"big_ring\"] = any_big or bool(base.get(\"big_ring\"))\n    return out\n\n\nif __name__ == \"__main__\":\n    print(f\"取代基拓扑增量库：{len(LIBRARY)} 条\")\n    for name in (\"Me\", \"Ph\", \"SO3H\", \"PhSO2\", \"NO2\", \"Bn\"):\n        d = delta_of(name)\n        print(f\"  {name:<8} → {d.expanded:<14} 环={list(d.ring_sizes)} \"\n              f\"杂原子={list(d.hetero)} 多环={d.contributes_multi}\")\n\n    base = {\"ring_sizes\": [], \"heteroatoms\": [], \"n_ring_systems\": 0,\n            \"has_ring\": False, \"has_multi_ring\": False,\n            \"has_fused_fragment\": False, \"has_disconnected_fragment\": False}\n    r = apply_deltas(base, [\"Ph\", \"NO2\"])\n    print(\"\\n示例：图上只有 Ph + NO2（主结构无环）\")\n    print(f\"  → 环={r['ring_sizes']} 杂原子={r['heteroatoms']} \"\n          f\"多环={r['has_multi_ring']} 非稠环片段={r['has_disconnected_fragment']}\")\n",
  },
  {
    path: "training/substituents.py",
    content: "\"\"\"训练③共享取代基库：元素 / 常见缩写 / 通式 / 烷基。\n\n条目固定三字段：hetero（含杂原子）、ring（自身带环）、smiles（SMILES 片段）。\nstyle.py 渲染与 topo.py 识别共用这一份；外部 JSON 通过 load_substituents 扩展。\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nfrom pathlib import Path\n\n_SUB = str.maketrans(\"₀₁₂₃₄₅₆₇₈₉\", \"0123456789\")\n_SUP = str.maketrans(\"⁰¹²³⁴⁵⁶⁷⁸⁹\", \"0123456789\")\n\n\ndef normalize_label_text(text: str) -> str:\n    \"\"\"下标/上标数字归一为普通数字并去空白——古早图下标极小，OCR 常丢。\"\"\"\n    return \"\".join(str(text).strip().translate(_SUB).translate(_SUP).split())\n\n\ndef _entry(smiles: str, hetero: bool = False, ring: bool = False) -> dict:\n    return {\"hetero\": hetero, \"ring\": ring, \"smiles\": smiles}\n\n\nSUBSTITUENTS: dict[str, dict] = {\n    # 元素\n    \"C\": _entry(\"C\"),\n    \"N\": _entry(\"N\", hetero=True),\n    \"O\": _entry(\"O\", hetero=True),\n    \"S\": _entry(\"S\", hetero=True),\n    \"P\": _entry(\"P\", hetero=True),\n    \"F\": _entry(\"F\", hetero=True),\n    \"Cl\": _entry(\"Cl\", hetero=True),\n    \"Br\": _entry(\"Br\", hetero=True),\n    \"I\": _entry(\"I\", hetero=True),\n    \"Si\": _entry(\"[Si]\", hetero=True),\n    # 常见缩写\n    \"Me\": _entry(\"C\"),\n    \"Et\": _entry(\"CC\"),\n    \"Pr\": _entry(\"CCC\"),\n    \"i-Pr\": _entry(\"C(C)C\"),\n    \"t-Bu\": _entry(\"CC(C)(C)\"),\n    \"Bu\": _entry(\"CCCC\"),\n    \"s-Bu\": _entry(\"CCC(C)\"),\n    \"Ph\": _entry(\"c1ccccc1\", ring=True),\n    \"Bn\": _entry(\"Cc1ccccc1\", ring=True),\n    \"Bz\": _entry(\"C(=O)c1ccccc1\", ring=True),\n    \"Cy\": _entry(\"C1CCCCC1\", ring=True),\n    \"Ac\": _entry(\"CC(=O)\"),\n    \"OMe\": _entry(\"OC\", hetero=True),\n    \"OEt\": _entry(\"OCC\", hetero=True),\n    \"OPh\": _entry(\"Oc1ccccc1\", hetero=True, ring=True),\n    \"OH\": _entry(\"O\", hetero=True),\n    \"NH2\": _entry(\"N\", hetero=True),\n    \"NMe2\": _entry(\"N(C)C\", hetero=True),\n    \"NEt2\": _entry(\"N(CC)CC\", hetero=True),\n    \"NHMe\": _entry(\"NC\", hetero=True),\n    \"NO2\": _entry(\"[N+](=O)[O-]\", hetero=True),\n    \"NO\": _entry(\"N=O\", hetero=True),\n    \"N3\": _entry(\"N=[N+]=[N-]\", hetero=True),\n    \"CN\": _entry(\"C#N\", hetero=True),\n    \"NC\": _entry(\"[N+]#[C-]\", hetero=True),\n    \"CO2Me\": _entry(\"C(=O)OC\", hetero=True),\n    \"CO2Et\": _entry(\"C(=O)OCC\", hetero=True),\n    \"CHO\": _entry(\"C=O\", hetero=True),\n    \"CONH2\": _entry(\"C(=O)N\", hetero=True),\n    \"SO3H\": _entry(\"S(=O)(=O)O\", hetero=True),\n    \"CF3\": _entry(\"C(F)(F)F\", hetero=True),\n    \"CCl3\": _entry(\"C(Cl)(Cl)Cl\", hetero=True),\n    \"TMS\": _entry(\"[Si](C)(C)C\", hetero=True),\n    \"Vi\": _entry(\"C=C\"),\n    \"All\": _entry(\"CC=C\"),\n    # 带撇号的通式（用不同 attachment map 号区分）\n    \"R\": _entry(\"[*:1]\"),\n    \"R'\": _entry(\"[*:2]\"),\n    \"R''\": _entry(\"[*:3]\"),\n    # 烷基 / 分子式写法\n    \"CH3\": _entry(\"C\"),\n    \"C2H5\": _entry(\"CC\"),\n    \"C3H7\": _entry(\"CCC\"),\n    \"C4H9\": _entry(\"CCCC\"),\n    \"C6H5\": _entry(\"c1ccccc1\", ring=True),\n}\n\n\ndef load_substituents(path: str | Path | None = None) -> dict:\n    \"\"\"返回内置库的副本；path 给定时把外部 JSON 条目合并进去（同名覆盖）。\n\n    JSON 形状：{\"新缩写\": {\"hetero\": bool, \"ring\": bool, \"smiles\": str}, ...}\n    \"\"\"\n    data = {name: dict(entry) for name, entry in SUBSTITUENTS.items()}\n    if path is None:\n        return data\n    p = Path(path)\n    if not p.exists():\n        raise FileNotFoundError(f\"取代基扩展文件不存在: {p}\")\n    extra = json.loads(p.read_text(encoding=\"utf-8\"))\n    if extra is None:\n        return data\n    if not isinstance(extra, dict):\n        raise ValueError(\"取代基 JSON 顶层必须是对象\")\n    for name, raw in extra.items():\n        if not isinstance(raw, dict):\n            raise ValueError(f\"取代基 {name} 的条目必须是对象\")\n        data[str(name)] = {\n            \"hetero\": bool(raw.get(\"hetero\", False)),\n            \"ring\": bool(raw.get(\"ring\", False)),\n            \"smiles\": str(raw.get(\"smiles\", \"\")),\n        }\n    return data\n\n\ndef match_substituent(text: str) -> dict | None:\n    \"\"\"在文本中找取代基：先整体精确（忽略大小写），再取最长子串。\"\"\"\n    s = normalize_label_text(text)\n    if not s:\n        return None\n    if s in SUBSTITUENTS:\n        return dict(SUBSTITUENTS[s])\n    low = s.lower()\n    for name in sorted(SUBSTITUENTS, key=len, reverse=True):\n        if name.lower() == low:\n            return dict(SUBSTITUENTS[name])\n    for name in sorted(SUBSTITUENTS, key=len, reverse=True):\n        if name.lower() in low:\n            return dict(SUBSTITUENTS[name])\n    return None\n\n\ndef save_substituents(data: dict, path: str | Path) -> None:\n    \"\"\"把库写成 UTF-8 JSON（中文注释可读）。\"\"\"\n    p = Path(path)\n    p.parent.mkdir(parents=True, exist_ok=True)\n    p.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding=\"utf-8\")\n",
  },
  {
    path: "training/topo.py",
    content: "\"\"\"训练③：结构式图 → 拓扑指标（环数 / 环大小 / 标签）。\n\n只用环数、环大小、标签，绝不用边数：缩写/显式氢让扫描图的边数不可数。\n\n关键取舍：\n  - 不用 cv2.HoughCircles——古早图的正电荷 ⊕ 是“小圆圈加号”，会被当成苯环。\n    改用轮廓闭合/嵌套 + skimage 骨架化 + 并查集数独立环，并按半径过滤。\n  - 字符识别用按风格档位建立的字符模板（cv2.matchTemplate），通用 OCR 默认不启用。\n\n可单独调试：\n    python -m training.topo templates --samples <dir> --out <templates.json>\n    python -m training.topo rings <image>\n    python -m training.topo topo <image> --templates <templates.json> --out <json>\n    python -m training.topo evaluate --results <dir> --truth <truth.csv>\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport base64\nimport csv\nimport json\nimport sys\nfrom pathlib import Path\n\nimport cv2\nimport numpy as np\nfrom skimage.morphology import skeletonize\n\ntry:\n    from .substituents import match_substituent, normalize_label_text\nexcept ImportError:  # 允许 python training/topo.py 直接跑\n    from substituents import match_substituent, normalize_label_text\n\nIMAGE_EXTS = (\".png\", \".jpg\", \".jpeg\", \".bmp\", \".tif\", \".tiff\")\n\n\nclass TopoResult(dict):\n    \"\"\"dict 子类：保留旧版 .to_json() / 属性访问，pipeline.py 不用跟着改。\"\"\"\n\n    def to_json(self) -> str:\n        return json.dumps(self, ensure_ascii=False, indent=2)\n\n    def __getattr__(self, key: str):\n        try:\n            return self[key]\n        except KeyError:\n            raise AttributeError(key) from None\n\n\ndef _warn(warnings: list[str] | None, msg: str) -> None:\n    if warnings is not None and msg not in warnings:\n        warnings.append(msg)\n    print(f\"[topo 警告] {msg}\", file=sys.stderr)\n\n\ndef _read_gray(path: str | Path) -> np.ndarray:\n    img = cv2.imread(str(path), cv2.IMREAD_GRAYSCALE)\n    if img is None:\n        raise ValueError(f\"读不了图片: {path}\")\n    return img\n\n\ndef _ink_binary(gray: np.ndarray) -> np.ndarray:\n    \"\"\"墨的二值化。\n\n    全图 Otsu 的阈值由面积大、墨浓的原子标签主导；遇到极细或印刷点状的\n    键线，最细的那批可能被判成背景。改成 **Otsu ∪ 自适应**：\n    正常图两者重合（不影响原有行为），极细线由自适应兜底。\n    实测（40 张、以原图灰度为真值）：旧 Otsu 找回中位 0.991 / p10 0.972，\n    新并集 1.000 / 0.999，每图平均多找回 54 像素。\n\n    高斯模糊保留：它对扫描噪点有抗噪作用，且实测不伤害 2~3px 的键线。\n    \"\"\"\n    blur = cv2.GaussianBlur(gray, (3, 3), 0)\n    _, bw = cv2.threshold(blur, 0, 255, cv2.THRESH_BINARY_INV + cv2.THRESH_OTSU)\n    ad = cv2.adaptiveThreshold(gray, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C,\n                               cv2.THRESH_BINARY_INV, 31, 10)\n    return (((bw > 0) | (ad > 0))).astype(np.uint8) * 255\n\n\ndef _finding(kind: str, size: int, confidence: float, bbox: list[int]) -> dict:\n    return {\"kind\": kind, \"size\": int(size), \"confidence\": round(float(confidence), 3),\n            \"bbox\": [int(v) for v in bbox]}\n\n\n# --------------------------------------------------------------------------\n# 坑2 / 坑4：按风格档位建字符模板 + 模板匹配（数字模板低阈值 + 警告）\n# --------------------------------------------------------------------------\n\ndef build_templates(sample_dir: str | Path, out_path: str | Path) -> dict:\n    \"\"\"从标注字符小图建模板库；文件名（去扩展名）即字符，如 N.png / Me.png / 2.png。\n\n    sample_dir 下有子目录时，子目录名即风格档位（如 1937 / 1971）；否则用 default 单档。\n    模板图裁到墨迹外接框并二值化，base64 存进 JSON，便于随结果一起归档。\n    \"\"\"\n    root = Path(sample_dir)\n    if not root.is_dir():\n        raise NotADirectoryError(f\"模板样本目录不存在: {root}\")\n    tiers = [p for p in sorted(root.iterdir()) if p.is_dir()]\n    groups = [(p.name, p) for p in tiers] if tiers else [(\"default\", root)]\n\n    templates: list[dict] = []\n    warnings: list[str] = []\n    for style, folder in groups:\n        for p in sorted(folder.iterdir()):\n            if p.suffix.lower() not in IMAGE_EXTS:\n                continue\n            text = p.stem\n            if not text:\n                continue\n            crop = _ink_binary(_read_gray(p))\n            ys, xs = np.nonzero(crop)\n            if len(xs) == 0:\n                _warn(warnings, f\"模板 {p.name} 全白，已跳过\")\n                continue\n            crop = crop[ys.min():ys.max() + 1, xs.min():xs.max() + 1]\n            ok, buf = cv2.imencode(\".png\", crop)\n            if not ok:\n                _warn(warnings, f\"模板 {p.name} 编码失败，已跳过\")\n                continue\n            templates.append({\n                \"text\": text,\n                \"style\": style,\n                \"w\": int(crop.shape[1]),\n                \"h\": int(crop.shape[0]),\n                \"image\": base64.b64encode(buf.tobytes()).decode(\"ascii\"),\n            })\n\n    if not templates:\n        _warn(warnings, f\"模板目录没有可用字符图: {root}（先标注 N.png / Me.png / 2.png 等）\")\n    payload = {\n        \"version\": 1,\n        \"threshold\": 0.72,\n        \"digit_threshold\": 0.58,\n        \"templates\": templates,\n        \"warnings\": warnings,\n    }\n    out = Path(out_path)\n    out.parent.mkdir(parents=True, exist_ok=True)\n    out.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding=\"utf-8\")\n    return payload\n\n\ndef _decode_template(item: dict) -> np.ndarray:\n    arr = np.frombuffer(base64.b64decode(item[\"image\"]), dtype=np.uint8)\n    img = cv2.imdecode(arr, cv2.IMREAD_GRAYSCALE)\n    if img is None:\n        raise ValueError(f\"模板 {item.get('text')!r} 解码失败\")\n    return (img > 127).astype(np.uint8) * 255\n\n\ndef _nms(items: list[dict], threshold: float = 0.5) -> list[dict]:\n    order = sorted(range(len(items)), key=lambda i: (-items[i][\"confidence\"], -len(items[i][\"text\"])))\n    kept: list[dict] = []\n    for i in order:\n        a = items[i]\n        ax, ay, aw, ah = a[\"bbox\"]\n        if any(_overlap_ratio(a[\"bbox\"], b[\"bbox\"]) > threshold for b in kept):\n            continue\n        kept.append(a)\n    return kept\n\n\ndef _overlap_ratio(a: list[int], b: list[int]) -> float:\n    ix = max(0, min(a[0] + a[2], b[0] + b[2]) - max(a[0], b[0]))\n    iy = max(0, min(a[1] + a[3], b[1] + b[3]) - max(a[1], b[1]))\n    return ix * iy / max(1, min(a[2] * a[3], b[2] * b[3]))\n\n\ndef _merge_subscripts(findings: list[dict], warnings: list[str] | None) -> list[dict]:\n    \"\"\"把紧邻前字的数字（C₂H₅ 的 2、5）并回去，孤立数字单独保留并告警。\"\"\"\n    digits = [f for f in findings if f[\"text\"].isdigit()]\n    others = [f for f in findings if not f[\"text\"].isdigit()]\n    merged: set[int] = set()\n    for d in digits:\n        dx, dy, dw, dh = d[\"bbox\"]\n        best, best_gap = None, 1e9\n        for o in others:\n            ox, oy, ow, oh = o[\"bbox\"]\n            gap = dx - (ox + ow)\n            if -2 <= gap <= 6 and abs((oy + oh / 2) - (dy + dh / 2)) <= max(8, dh) and gap < best_gap:\n                best, best_gap = o, gap\n        if best is None:\n            _warn(warnings, f\"孤立数字标签 {d['text']!r} 未并入相邻字符，已单独保留\")\n            continue\n        best[\"text\"] = normalize_label_text(best[\"text\"] + d[\"text\"])\n        best[\"confidence\"] = round(min(best[\"confidence\"], d[\"confidence\"]), 3)\n        merged.add(id(d))\n    return others + [d for d in digits if id(d) not in merged]\n\n\ndef read_labels_with_templates(image_path, templates_path, warnings: list[str] | None = None) -> list[dict]:\n    \"\"\"用 cv2.matchTemplate 找标签，返回 [{'text','bbox','confidence'}]。\n\n    warnings 为可选外部列表，便于 extract_topology 汇总；数字模板用更低阈值并写明告警。\n    通用 OCR（pytesseract 等）不作为默认路径——跨时代字体漂移下不可靠。\n    \"\"\"\n    payload = json.loads(Path(templates_path).read_text(encoding=\"utf-8\"))\n    templates = payload.get(\"templates\", [])\n    if not templates:\n        _warn(warnings, f\"模板库为空: {templates_path}\")\n        return []\n    ink = _ink_binary(_read_gray(image_path))\n    base_t = float(payload.get(\"threshold\", 0.72))\n    digit_t = float(payload.get(\"digit_threshold\", max(0.5, base_t - 0.14)))\n\n    raw: list[dict] = []\n    for item in templates:\n        tpl = _decode_template(item)\n        th, tw = tpl.shape\n        if th > ink.shape[0] or tw > ink.shape[1]:\n            continue\n        text = str(item[\"text\"])\n        threshold = digit_t if text.isdigit() else base_t\n        res = cv2.matchTemplate(ink, tpl, cv2.TM_CCOEFF_NORMED)\n        ys, xs = np.where(res >= threshold)\n        for y, x in zip(ys, xs):\n            conf = float(res[y, x])\n            if text.isdigit() and conf < base_t:\n                _warn(warnings, f\"数字模板 {text!r} 置信度仅 {conf:.2f}（下标极小，易漏，已按低阈值收录）\")\n            raw.append({\"text\": text, \"bbox\": [int(x), int(y), int(tw), int(th)],\n                        \"confidence\": round(conf, 3)})\n    return _merge_subscripts(_nms(raw), warnings)\n\n\n# --------------------------------------------------------------------------\n# 坑1 / 坑5：环检测不用 HoughCircles\n# --------------------------------------------------------------------------\n\ndef _contour_rings(ink: np.ndarray, warnings: list[str] | None) -> list[dict]:\n    \"\"\"轮廓环检测。手绘/扫描图线条常断裂，先做闭运算接缝再找内洞。\n\n    实测：同一张真结构式（六元环手绘圆圈），不闭合时环数=0；\n    MORPH_CLOSE k=6 后内洞成形、近似边数=6 正确。k 太小接不上，太大把相邻环并一起，\n    取 6 是这几类古早图的折中（更细的图可用 4）。\n    \"\"\"\n    # 断线修补：闭运算把笔画间的 1~3px 缺口接上，否则 findContours 拿不到内洞\n    kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (6, 6))\n    ink_closed = cv2.morphologyEx(ink, cv2.MORPH_CLOSE, kernel)\n\n    contours, hierarchy = cv2.findContours(ink_closed, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)\n    if hierarchy is None:\n        return []\n    hierarchy = hierarchy[0]\n    out: list[dict] = []\n    for i, c in enumerate(contours):\n        area = cv2.contourArea(c)\n        if area < 120:\n            continue\n        peri = cv2.arcLength(c, True)\n        if peri <= 0:\n            continue\n        x, y, w, h = cv2.boundingRect(c)\n        _, encloser_r = cv2.minEnclosingCircle(c)\n        fill_ratio = area / max(1e-6, np.pi * encloser_r ** 2)\n        # 电荷 ⊕ 半径 <10px：明确忽略，绝不当苯环（HoughCircles 在这里必错）\n        if encloser_r < 10:\n            continue\n        if fill_ratio > 0.9 and encloser_r > 15 and encloser_r <= 90:\n            # 古早圆苯环半径 >15px；10~15px 的多为电荷/符号，不认。\n            # 用最小外接圆填充率而非圆度：正六边形圆度也有 0.9，但填充率只有约 0.83。\n            out.append(_finding(\"circle\", 6, round(0.6 + 0.3 * fill_ratio, 3), [x, y, w, h]))\n            continue\n        child = hierarchy[i][2]\n        if child == -1 or cv2.contourArea(contours[child]) < 0.15 * area:\n            continue\n        inner = contours[child]\n        # 真环的内洞必须够大：小内洞多是被闭运算粘住的字母/符号（O、S、⊕ 之类）。\n        # 实测真六元环内洞面积 ≈160，误报的字母内洞 45~57，取 100 作为下限。\n        inner_area = cv2.contourArea(inner)\n        if inner_area < 100:\n            continue\n        n = len(cv2.approxPolyDP(inner, 0.045 * cv2.arcLength(inner, True), True))\n        if not 3 <= n <= 9:\n            n = len(cv2.approxPolyDP(c, 0.05 * peri, True))\n        if not 3 <= n <= 9:\n            n = 6\n        if not 0.35 < w / max(h, 1) < 3.0:\n            continue\n        out.append(_finding(\"polygon\", n, 0.7 if n <= 7 else 0.62, [x, y, w, h]))\n    return out\n\n\ndef _skeleton_rings(ink: np.ndarray, existing: list[dict], warnings: list[str] | None) -> list[dict]:\n    \"\"\"骨架图论补环：并查集数独立环 E-V+C，只补轮廓没确认到的部分。\"\"\"\n    try:\n        skel = skeletonize(ink > 0)\n    except Exception as exc:\n        _warn(warnings, f\"骨架化失败，跳过图论补环: {exc}\")\n        return []\n    pts = np.argwhere(skel)\n    if len(pts) == 0:\n        return []\n    height, width = skel.shape\n    index = np.full((height, width), -1, dtype=np.int64)\n    for k, (y, x) in enumerate(pts):\n        index[y, x] = k\n    # 只连右/下邻居：8 邻域会在拐角处造出假环\n    edges = []\n    for y, x in pts:\n        a = index[y, x]\n        for dy, dx in ((0, 1), (1, 0)):\n            ny, nx = int(y) + dy, int(x) + dx\n            if ny < height and nx < width:\n                b = index[ny, nx]\n                if b >= 0:\n                    edges.append((a, b))\n    parent = list(range(len(pts)))\n\n    def find(a: int) -> int:\n        while parent[a] != a:\n            parent[a] = parent[parent[a]]\n            a = parent[a]\n        return a\n\n    for a, b in edges:\n        ra, rb = find(a), find(b)\n        if ra != rb:\n            parent[rb] = ra\n    stats: dict[int, list[int]] = {}\n    for k in range(len(pts)):\n        stats.setdefault(find(k), [0, 0])[0] += 1\n    for a, b in edges:\n        stats[find(a)][1] += 1\n\n    out: list[dict] = []\n    for root, (v, e) in stats.items():\n        cycles = e - v + 1\n        if cycles <= 0:\n            continue\n        component = np.array([p for k, p in enumerate(pts) if find(k) == root])\n        y0, x0 = component.min(axis=0)\n        y1, x1 = component.max(axis=0) + 1\n        bbox = [int(x0), int(y0), int(x1 - x0), int(y1 - y0)]\n        if bbox[2] < 12 or bbox[3] < 12 or any(_overlap_ratio(bbox, f[\"bbox\"]) > 0.5 for f in existing):\n            continue\n        for _ in range(min(cycles, 4)):\n            out.append(_finding(\"skeleton\", 6, 0.55, bbox))\n        _warn(warnings, \"骨架图论检出环但轮廓未确认：环大小按 6 估计，可信度低\")\n    return out\n\n\ndef _dedupe_rings(findings: list[dict]) -> list[dict]:\n    priority = {\"polygon\": 0, \"circle\": 1, \"skeleton\": 2}\n    kept: list[dict] = []\n    for f in sorted(findings, key=lambda x: (priority.get(x[\"kind\"], 9), -x[\"confidence\"])):\n        if not any(_overlap_ratio(f[\"bbox\"], g[\"bbox\"]) > 0.5 for g in kept):\n            kept.append(f)\n    return kept\n\n\ndef detect_rings(image_path, warnings: list[str] | None = None) -> list[dict]:\n    \"\"\"返回 [{'kind','size','confidence','bbox'}]；不用 HoughCircles（⊕ 会冒充苯环）。\"\"\"\n    ink = _ink_binary(_read_gray(image_path))\n    findings = _contour_rings(ink, warnings)\n    findings += _skeleton_rings(ink, findings, warnings)\n    return _dedupe_rings(findings)\n\n\n# --------------------------------------------------------------------------\n# 汇总与人工真值回流\n# --------------------------------------------------------------------------\n\ndef extract_topology(image_path, templates_path=None) -> dict:\n    \"\"\"汇总拓扑：{'image','rings','ring_sizes','labels', 两类 findings, 'warnings'}。\"\"\"\n    warnings: list[str] = []\n    path = Path(image_path)\n    if not path.exists():\n        raise FileNotFoundError(f\"图片不存在: {path}\")\n    ring_findings = detect_rings(path, warnings)\n    ring_sizes = sorted(f[\"size\"] for f in ring_findings if f[\"size\"] > 0)\n\n    label_findings: list[dict] = []\n    if templates_path is None:\n        _warn(warnings, \"未提供字符模板：labels 为空（通用 OCR 默认不启用）\")\n    else:\n        label_findings = read_labels_with_templates(path, templates_path, warnings)\n    labels = sorted({normalize_label_text(f[\"text\"]) for f in label_findings if f[\"text\"]})\n    for text in labels:\n        if match_substituent(text) is None:\n            _warn(warnings, f\"标签 {text!r} 不在取代基库中，拓扑比对可能不准\")\n    if not ring_findings:\n        _warn(warnings, \"未检出环：可能是无环结构或图像质量不足\")\n\n    return TopoResult(\n        image=str(path),\n        rings=len(ring_findings),\n        ring_sizes=ring_sizes,\n        labels=labels,\n        ring_findings=ring_findings,\n        label_findings=label_findings,\n        warnings=warnings,\n    )\n\n\n_IMG_KEYS = (\"image\", \"file\", \"filename\", \"name\", \"path\", \"stem\", \"图片\")\n_RING_KEYS = (\"rings\", \"ring_count\", \"n_rings\", \"环数\")\n_SIZE_KEYS = (\"ring_sizes\", \"ringsizes\", \"ring size\", \"环大小\")\n_LABEL_KEYS = (\"labels\", \"label\", \"标签\")\n\n\ndef _cell(row: dict, keys: tuple[str, ...]) -> str | None:\n    lut = {str(k).strip().lower(): k for k in row if k}\n    for key in keys:\n        if key in lut:\n            return row[lut[key]]\n    return None\n\n\ndef _parse_list(value) -> list[str]:\n    if value is None:\n        return []\n    if isinstance(value, (list, tuple)):\n        values = [str(v) for v in value]\n    else:\n        s = str(value).strip()\n        if not s:\n            return []\n        if s.startswith(\"[\"):\n            try:\n                parsed = json.loads(s)\n                values = [str(v) for v in parsed] if isinstance(parsed, list) else [s]\n            except json.JSONDecodeError:\n                values = [s]\n        else:\n            values = next((s.split(sep) for sep in (\";\", \"|\", \",\", \"/\") if sep in s), s.split())\n    return [v.strip() for v in values if str(v).strip()]\n\n\ndef _ints(values) -> list[int]:\n    out = []\n    for v in values:\n        try:\n            out.append(int(float(str(v).strip())))\n        except (TypeError, ValueError):\n            continue\n    return sorted(out)\n\n\ndef evaluate(result_dir, truth_csv) -> dict:\n    \"\"\"用人工标注真值算准确率：逐字段 + 三字段全对（exact）。\n\n    truth CSV 需含图片名、rings、ring_sizes、labels 四列（列名大小写不敏感，\n    ring_sizes/labels 支持 JSON 数组或 ;|,/ 分隔）。结果目录取 *.topo.json。\n    \"\"\"\n    root = Path(result_dir)\n    if not root.is_dir():\n        raise NotADirectoryError(f\"结果目录不存在: {root}\")\n    results: dict[str, dict] = {}\n    for p in root.rglob(\"*.json\"):\n        try:\n            data = json.loads(p.read_text(encoding=\"utf-8\"))\n        except (OSError, json.JSONDecodeError):\n            continue\n        if not isinstance(data, dict) or \"rings\" not in data:\n            continue\n        stem = p.stem[:-5] if p.stem.endswith(\".topo\") else p.stem\n        results[stem] = data\n        image_stem = Path(str(data.get(\"image\", \"\"))).stem\n        if image_stem:\n            results[image_stem] = data\n\n    with open(truth_csv, newline=\"\", encoding=\"utf-8-sig\") as f:\n        rows = list(csv.DictReader(f))\n    warnings: list[str] = []\n    if not rows:\n        _warn(warnings, f\"真值 CSV 没有数据行: {truth_csv}\")\n    if not results:\n        _warn(warnings, f\"结果目录没有 topo JSON: {root}\")\n\n    details: list[dict] = []\n    field_ok = {\"rings\": [], \"ring_sizes\": [], \"labels\": []}\n    for row in rows:\n        name = (_cell(row, _IMG_KEYS) or \"\").strip()\n        key = Path(name).stem\n        data = results.get(key)\n        if data is None:\n            _warn(warnings, f\"真值 {name!r} 找不到对应结果 JSON\")\n            details.append({\"image\": name, \"matched\": False, \"ok_rings\": False,\n                            \"ok_ring_sizes\": False, \"ok_labels\": False, \"ok_all\": False})\n            continue\n\n        t_rings_raw = _cell(row, _RING_KEYS)\n        t_sizes_raw = _cell(row, _SIZE_KEYS)\n        t_labels_raw = _cell(row, _LABEL_KEYS)\n        p_sizes = _ints(data.get(\"ring_sizes\", []))\n        p_labels = {normalize_label_text(str(v)) for v in data.get(\"labels\", [])}\n        ok_rings = ok_sizes = ok_labels = False\n        if t_rings_raw not in (None, \"\"):\n            ok_rings = _ints([t_rings_raw]) == [int(data.get(\"rings\", -1))]\n            field_ok[\"rings\"].append(ok_rings)\n        if t_sizes_raw not in (None, \"\"):\n            ok_sizes = _ints(_parse_list(t_sizes_raw)) == p_sizes\n            field_ok[\"ring_sizes\"].append(ok_sizes)\n        if t_labels_raw not in (None, \"\"):\n            ok_labels = {normalize_label_text(v) for v in _parse_list(t_labels_raw)} == p_labels\n            field_ok[\"labels\"].append(ok_labels)\n        details.append({\"image\": name, \"matched\": True, \"ok_rings\": ok_rings,\n                        \"ok_ring_sizes\": ok_sizes, \"ok_labels\": ok_labels,\n                        \"ok_all\": ok_rings and ok_sizes and ok_labels})\n\n    exact = sum(1 for d in details if d[\"ok_all\"])\n    matched = sum(1 for d in details if d[\"matched\"])\n\n    def rate(values: list[bool]) -> float | None:\n        return round(sum(values) / len(values), 4) if values else None\n\n    return {\n        \"total\": len(rows),\n        \"matched\": matched,\n        \"accuracy\": round(exact / matched, 4) if matched else 0.0,\n        \"exact_accuracy\": round(exact / matched, 4) if matched else 0.0,\n        \"rings_accuracy\": rate(field_ok[\"rings\"]),\n        \"ring_sizes_accuracy\": rate(field_ok[\"ring_sizes\"]),\n        \"labels_accuracy\": rate(field_ok[\"labels\"]),\n        \"details\": details,\n        \"warnings\": warnings,\n    }\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(description=\"训练③：结构式图 → 拓扑指标\")\n    sub = ap.add_subparsers(dest=\"cmd\", required=True)\n\n    t = sub.add_parser(\"templates\", help=\"从标注字符小图建模板库\")\n    t.add_argument(\"--samples\", required=True, help=\"字符小图目录（子目录=风格档位）\")\n    t.add_argument(\"--out\", required=True, help=\"模板 JSON 输出路径\")\n\n    r = sub.add_parser(\"rings\", help=\"只检测环（不用 HoughCircles）\")\n    r.add_argument(\"image\")\n\n    p = sub.add_parser(\"topo\", help=\"提取完整拓扑\")\n    p.add_argument(\"image\")\n    p.add_argument(\"--templates\", help=\"字符模板 JSON；不给则 labels 为空\")\n    p.add_argument(\"--out\", help=\"结果 JSON 文件；不给则打印到 stdout\")\n\n    e = sub.add_parser(\"evaluate\", help=\"人工真值回流算准确率\")\n    e.add_argument(\"--results\", required=True, help=\"topo JSON 所在目录\")\n    e.add_argument(\"--truth\", required=True, help=\"人工标注 CSV\")\n    e.add_argument(\"--out\", help=\"评估报告 JSON；不给则打印到 stdout\")\n\n    args = ap.parse_args()\n    if args.cmd == \"templates\":\n        payload = build_templates(args.samples, args.out)\n        print(f\"写入 {len(payload['templates'])} 个模板 → {args.out}\")\n        for msg in payload[\"warnings\"]:\n            print(f\"[topo 警告] {msg}\", file=sys.stderr)\n    elif args.cmd == \"rings\":\n        findings = detect_rings(args.image)\n        if not findings:\n            print(\"[topo 警告] 未检出环：可能无环或图像质量不足\", file=sys.stderr)\n        print(json.dumps(findings, ensure_ascii=False, indent=2))\n    elif args.cmd == \"topo\":\n        result = extract_topology(args.image, args.templates)\n        text = result.to_json()\n        if args.out:\n            out = Path(args.out)\n            out.parent.mkdir(parents=True, exist_ok=True)\n            out.write_text(text, encoding=\"utf-8\")\n            print(f\"写出 {out}\")\n        else:\n            print(text)\n        print(f\"环数 {result['rings']} · 环大小 {result['ring_sizes']} · 标签 {result['labels']}\")\n    else:\n        report = evaluate(args.results, args.truth)\n        text = json.dumps(report, ensure_ascii=False, indent=2)\n        if args.out:\n            out = Path(args.out)\n            out.parent.mkdir(parents=True, exist_ok=True)\n            out.write_text(text, encoding=\"utf-8\")\n            print(f\"写出 {out}\")\n        else:\n            print(text)\n        print(f\"准确率 {report['accuracy']}（{report['matched']}/{report['total']}）\")\n\n\nif __name__ == \"__main__\":\n    main()\n",
  },
  {
    path: "training/verify_glyph_match.py",
    content: "\"\"\"验证：正文采集的字符模板能否识别结构式里的小字。\n\n这是用户洞察的直接检验：\n    「正文中的字和结构式用的字体是同一种，只是大小不一样。」\n\n若能识别，则\"是不是 C\"变成查表，不再靠几何猜——\n所有内容泄漏（把 O 当碳、把杂原子串当缩写块）都会随之消失。\n\n用法：\n    python -m training.verify_glyph_match --templates <pkl> --image <结构式裁图>\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport pickle\nfrom pathlib import Path\n\nimport numpy as np\n\nfrom .notation import _ink, _read_gray, _split_lines_and_glyphs\nfrom .pdf_glyphs import match_glyph\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(prog=\"csd-verify-glyph\")\n    ap.add_argument(\"--templates\", required=True)\n    ap.add_argument(\"--images\", nargs=\"+\", required=True, help=\"一个或多个结构式裁图\")\n    args = ap.parse_args()\n\n    with open(args.templates, \"rb\") as fh:\n        pack = pickle.load(fh)\n    templates = pack[\"templates\"]\n\n    for img in args.images:\n        gray = _read_gray(img)\n        h, w = gray.shape\n        diag = (h ** 2 + w ** 2) ** 0.5\n        ink = _ink(gray)\n        _, boxes, _, _ = _split_lines_and_glyphs(ink, h, w, diag)\n        print(f\"\\n=== {Path(img).name}  字形 {len(boxes)}\")\n\n        import cv2\n        # 逐个字形裁出来匹配\n        results = []\n        for (x, y, bw, bh) in boxes:\n            crop = gray[y:y + bh, x:x + bw]\n            if crop.size == 0:\n                continue\n            _, b = cv2.threshold(crop, 0, 255,\n                                 cv2.THRESH_BINARY_INV + cv2.THRESH_OTSU)\n            ch, score = match_glyph(b, templates)\n            results.append((ch, score, bw, bh))\n\n        # 汇总：这张图里有几个 C、几个 O\n        from collections import Counter\n        cnt = Counter(ch for ch, _, _, _ in results if ch)\n        strong = Counter(ch for ch, s, _, _ in results if ch and s >= 0.55)\n        print(f\"  识别(全): {dict(sorted(cnt.items(), key=lambda kv: -kv[1])[:10])}\")\n        print(f\"  识别(≥0.55): {dict(sorted(strong.items(), key=lambda kv: -kv[1])[:10])}\")\n        c_n = strong.get(\"C\", 0)\n        o_n = strong.get(\"O\", 0)\n        n_n = strong.get(\"N\", 0)\n        print(f\"  → C={c_n}  O={o_n}  N={n_n}   \"\n              f\"（有 C 且 C 占多数 ⇒ 显式碳式；只有 O/N ⇒ 键线式）\")\n        for ch, s, bw, bh in results[:10]:\n            print(f\"     '{ch}' {s:.2f}  bbox={bw}x{bh}\")\n\n\nif __name__ == \"__main__\":\n    main()\n",
  },
  {
    path: "training/verify_style_invariance.py",
    content: "\"\"\"红线验证：同一画法、不同内容（环数/原子数/支链多少）→ 分数必须相近。\n\n用户明确要求：\"注意不要混淆绘画风格和内容（比如是否有环是内容）\"。\n这个脚本就是对这条红线的**实证检验**，不是口头保证：\n用 RDKit 按同一种渲染参数画不同分子（1环/2环/3环/链状/多原子），\n若特征分数随内容大幅波动，说明特征泄漏了内容，必须修。\n\n用法：python -m training.verify_style_invariance\n\"\"\"\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nfrom .notation import FEATURE_NAMES, extract_notation\nfrom .notation_clf import density_score\n\n# 同一画法下内容差异极大的分子组\nGROUPS = {\n    \"chain_small\": [\"CCO\", \"CCCC\", \"CC(C)C\"],\n    \"chain_large\": [\"CCCCCCCC\", \"CCCCCCCCCCCC\", \"CCCCCCCCCCCCCCCCCC\"],\n    \"ring_one\": [\"c1ccccc1\", \"C1CCCCC1\", \"c1ccncc1\"],\n    \"ring_two\": [\"c1ccc2ccccc2c1\", \"C1CC2CCC1C2\"],\n    \"ring_three\": [\"c1ccc2c(c1)ccc1ccccc12\", \"C1CC2CC3CC1C2C3\"],\n    \"hetero_many\": [\"O=C(O)c1ccccc1\", \"N#Cc1ccc(O)cc1\", \"O=S(=O)(O)c1ccccc1\"],\n}\n\n\ndef _render(smiles: str, out: Path, font: str, line_w: float, font_size: int) -> bool:\n    \"\"\"用固定渲染参数画图——参数完全不随分子变化，这就是\"同一种画法\"。\"\"\"\n    from rdkit import Chem\n    from rdkit.Chem import AllChem, Draw\n    from rdkit.Chem.Draw import rdMolDraw2D\n\n    m = Chem.MolFromSmiles(smiles)\n    if m is None:\n        return False\n    AllChem.Compute2DCoords(m)\n    d = rdMolDraw2D.MolDraw2DCairo(320, 240)\n    o = d.drawOptions()\n    o.bondLineWidth = line_w\n    o.baseFontSize = font_size\n    o.addStereoAnnotation = False\n    o.clearBackground = True\n    o.useBWAtomPalette()          # 单色，避免颜色成为额外线索\n    if font and Path(font).exists():\n        o.fontFile = font\n    rdMolDraw2D.PrepareAndDrawMolecule(d, m)\n    d.FinishDrawing()\n    out.write_bytes(d.GetDrawingText())\n    return True\n\n\ndef main() -> None:\n    # 输出到 ASCII 路径：cv2.imread 读不了含中文的路径\n    out_dir = Path(\"F:/2026-11-22-10-10-52/.workbuddy/invariance_ascii\")\n    out_dir.mkdir(parents=True, exist_ok=True)\n    font = r\"C:\\Windows\\Fonts\\times.ttf\"\n\n    print(\"同一画法（固定线宽/字号/单色），只改分子内容，看分数是否稳定：\\n\")\n    print(f\"{'组':>10} {'n':>3} {'score均值':>9} {'标准差':>7} {'极差':>7}  明细\")\n    worst = 0.0\n    for gname, smis in GROUPS.items():\n        scores = []\n        detail = []\n        for i, smi in enumerate(smis):\n            p = out_dir / f\"{gname}_{i}.png\"\n            if _render(smi, p, font, 1.2, 14):\n                f = extract_notation(p)\n                s = density_score(f)\n                scores.append(s)\n                detail.append(f\"{s:.3f}\")\n        if not scores:\n            print(f\"{gname:>10} 渲染失败\")\n            continue\n        import statistics\n        mean = statistics.mean(scores)\n        sd = statistics.pstdev(scores) if len(scores) > 1 else 0.0\n        rng = max(scores) - min(scores)\n        worst = max(worst, rng)\n        print(f\"{gname:>10} {len(scores):>3} {mean:>9.3f} {sd:>7.3f} {rng:>7.3f}  {' '.join(detail)}\")\n\n    print()\n    print(\"判读标准：同一画法下，分数极差应远小于不同画法之间的差异（约 0.3）。\")\n    print(f\"本次最大极差 {worst:.3f} → \" +\n          (\"通过：内容差异没有污染风格分数\" if worst < 0.15 else \"未通过：特征泄漏了内容，需修\"))\n\n\nif __name__ == \"__main__\":\n    main()\n",
  },
  {
    path: "training/verify_style_separation.py",
    content: "\"\"\"反向验证：同一个分子，用不同画法渲染 → 分数必须拉开。\n\n红线有两面：\n    正面（已过 verify_style_invariance）：同画法不同内容 → 分数稳定\n    反面（本脚本）：  同内容不同画法 → 分数必须显著不同\n两面都过，才证明特征量的是\"画法\"而不是\"内容\"或别的杂物。\n\n三种画法用 RDKit 参数模拟：\n    dense     把所有碳的 H 显式写出来（Chem.AddHs + 显式 C 标签）\n    hybrid    只给部分原子加显式标签\n    skeletal  标准键线式（碳原子隐式）\n\n用法：python -m training.verify_style_separation\n\"\"\"\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nfrom .notation import extract_notation\nfrom .notation_clf import density_score\n\nMOLS = [\"c1ccccc1\", \"CCCCCC\", \"c1ccc(cc1)C(=O)O\", \"C1CCCCC1\"]\n\n\ndef _render(smiles: str, mode: str, out: Path) -> bool:\n    from rdkit import Chem\n    from rdkit.Chem import AllChem\n    from rdkit.Chem.Draw import rdMolDraw2D\n\n    m = Chem.MolFromSmiles(smiles)\n    if m is None:\n        return False\n\n    d = rdMolDraw2D.MolDraw2DCairo(420, 320)\n    o = d.drawOptions()\n    o.useBWAtomPalette()\n    o.clearBackground = True\n    o.addStereoAnnotation = False\n\n    if mode == \"dense\":\n        # 早期\"所有碳都画\"：每个碳顶点直接写 CH3 / CH2 / CH / C（这就是 JACS 1900\n        # 那批图的真实画法），并加大键长让标签放得下，避免字压线。\n        for a in m.GetAtoms():\n            if a.GetSymbol() != \"C\":\n                continue\n            nh = a.GetTotalNumHs()\n            a.SetProp(\"atomLabel\", f\"CH{nh}\" if nh else \"C\")\n        AllChem.Compute2DCoords(m)\n        o.bondLineWidth = 1.0\n        o.baseFontSize = 13\n        o.fixedBondLength = 58          # 加大键长，给字腾地方\n        d.DrawMolecule(m)\n        for a in m.GetAtoms():     # 画完清掉，避免污染后续复用\n            if a.HasProp(\"atomLabel\"):\n                a.ClearProp(\"atomLabel\")\n    elif mode == \"hybrid\":\n        # 混合式：骨架键线，甲基显式写出（Me/CH3），其余碳隐式\n        o.bondLineWidth = 1.2\n        o.baseFontSize = 14\n        o.explicitMethyl = True\n        o.fixedBondLength = 48\n        AllChem.Compute2DCoords(m)\n        d.DrawMolecule(m)\n    else:\n        o.bondLineWidth = 1.2\n        o.baseFontSize = 14\n        o.fixedBondLength = 48\n        AllChem.Compute2DCoords(m)\n        d.DrawMolecule(m)\n\n    d.FinishDrawing()\n    out.write_bytes(d.GetDrawingText())\n    return True\n\n\ndef main() -> None:\n    out_dir = Path(\"F:/2026-11-22-10-10-52/.workbuddy/sep_ascii\")\n    out_dir.mkdir(parents=True, exist_ok=True)\n\n    print(\"同一个分子换画法 → 分数应显著上升（skeletal < hybrid < dense）\\n\")\n    print(f\"{'分子':>22} {'skeletal':>9} {'hybrid':>9} {'dense':>9}  {'dense-sk':>9}\")\n    gaps = []\n    for i, smi in enumerate(MOLS):\n        got = {}\n        for mode in (\"skeletal\", \"hybrid\", \"dense\"):\n            p = out_dir / f\"m{i}_{mode}.png\"\n            if not _render(smi, mode, p):\n                continue\n            got[mode] = density_score(extract_notation(p))\n        if len(got) < 3:\n            print(f\"{smi:>22} 渲染不全\")\n            continue\n        gap = got[\"dense\"] - got[\"skeletal\"]\n        gaps.append(gap)\n        print(f\"{smi:>22} {got['skeletal']:>9.3f} {got['hybrid']:>9.3f} {got['dense']:>9.3f}  {gap:>9.3f}\")\n\n    print()\n    if gaps:\n        import statistics\n        mean_gap = statistics.mean(gaps)\n        print(f\"平均分离度 {mean_gap:.3f} → \" +\n              (\"通过：不同画法被明确区分\" if mean_gap > 0.25 else \"未通过：画法区分不足\"))\n\n\nif __name__ == \"__main__\":\n    main()\n",
  },
  {
    path: "training/vertices.py",
    content: "\"\"\"从结构式裁图识别顶点：擦字 → 边拟合 → 双向延长 → 求交合并。\n\n判据来自用户逐条口述（2026-11-26），不是设计者的自由发挥：\n\n1. 字块要尽量跟实际的字差不多大，把字块换成球/顶点。\n2. 擦字：只擦字笔画本身，不按 bbox 整块擦、不膨胀——否则会把穿过字的键一起擦掉。\n3. 擦字后剩下的每个连通域就是一条完整的边，拟合成直线（不找骨架端点）。\n   用户原话：「画一个六边形，把 6 个角擦掉，只要把这 6 条边双向延长，\n   它最终还是会成为一个六边形」。\n4. 键一定有两头，不管多短都要沿自身方向往两端延长；最多延长到一个阈值\n   （不会超出页面、也不会过于长）。实测阈值取 2.5 字高。\n5. 交点合并：距离近 **且** 夹角合理，才并成一个顶点。\n   用户画圈说明：一个角上可能挤着好几个两两交点（多线交一点、双键），\n   但那仍是一个顶点；阈值不能太激进，否则双键或画得不规范处会被拆成两点。\n6. 残笔过滤：真键宽 3~5px，字母残笔宽 1~2px，按宽度分开。\n   用户原话：「碳氢没有擦干净，氢的竖线还留着」→ 宽<3px 丢掉；\n   「它还是很粗的，它就是键」→ 短但粗的键保留。\n\n状态：顶点识别在人工核对过的样本上成立（1975/1906 六元环均为 6 顶点）。\n环的分类（小环/大环/中环、单环/多环）尚未稳定，不在本模块范围。\n\"\"\"\nfrom __future__ import annotations\n\nimport math\nfrom pathlib import Path\n\nimport numpy as np\n\nANISO_GLYPH = 0.55\nMIN_BOND_WIDTH = 3          # 宽 < 3px 的连通域 = 字母残笔\nMIN_AREA_FRAC = 0.02        # 面积下限（按字高平方）\nEXTEND_CH = 2.5             # 边延长上限（字高倍数）\nMERGE_DIST_CH = 1.2         # 交点合并距离（字高倍数）\nMERGE_ANGLE = (35.0, 135.0) # 交点合并的夹角合理区间（取锐角后判定）\n\n\ndef ink_binary(gray):\n    \"\"\"墨的二值化：Otsu ∪ 自适应，细线用自适应兜底。\"\"\"\n    import cv2\n\n    blur = cv2.GaussianBlur(gray, (3, 3), 0)\n    _, bw = cv2.threshold(blur, 0, 255, cv2.THRESH_BINARY_INV + cv2.THRESH_OTSU)\n    ad = cv2.adaptiveThreshold(gray, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C,\n                               cv2.THRESH_BINARY_INV, 31, 10)\n    return (((bw > 0) | (ad > 0))).astype(np.uint8)\n\n\ndef _char_height(ink):\n    import cv2\n\n    n0, _l0, s0, _ = cv2.connectedComponentsWithStats(ink, connectivity=8)\n    hs = [int(s0[i, cv2.CC_STAT_HEIGHT]) for i in range(1, n0)\n          if int(s0[i, cv2.CC_STAT_AREA]) >= 20]\n    return float(np.median(hs)) if hs else 12.0\n\n\ndef split_glyph_stroke(gray, ink=None, ch=None):\n    \"\"\"按结构张量的局部方向一致性，把墨分为字 / 线。\n\n    线单向延伸 → 各向异性高；字的笔画多向交汇 → 低。\n    与斜率、折线、图缩放无关。\n    \"\"\"\n    import cv2\n\n    if ink is None:\n        ink = ink_binary(gray)\n    if ch is None:\n        ch = _char_height(ink)\n    if int(ink.sum()) < 300:\n        return None, None, ch\n\n    ks = int(max(5, ch * 0.55 * 2)) // 2 * 2 + 1\n    b = (ink * 255).astype(np.uint8)\n    gx = cv2.Sobel(b.astype(np.float32), cv2.CV_32F, 1, 0, ksize=3)\n    gy = cv2.Sobel(b.astype(np.float32), cv2.CV_32F, 0, 1, ksize=3)\n    m = cv2.blur(ink.astype(np.float32), (ks, ks)) + 1e-6\n    sxx = cv2.blur(gx * gx, (ks, ks)) / m\n    syy = cv2.blur(gy * gy, (ks, ks)) / m\n    sxy = cv2.blur(gx * gy, (ks, ks)) / m\n    tr = sxx + syy\n    det = sxx * syy - sxy * sxy\n    disc = np.sqrt(np.maximum(tr * tr / 4 - det, 0))\n    aniso = ((tr / 2 + disc) - (tr / 2 - disc)) / (tr + 1e-6)\n    glyph = ((ink > 0) & (aniso < ANISO_GLYPH)).astype(np.uint8) * 255\n    stroke = ((ink > 0) & (aniso > 0.75)).astype(np.uint8) * 255\n    return glyph, stroke, ch\n\n\ndef remove_glyphs(gray, glyph=None):\n    \"\"\"擦掉字笔画，返回 (去字灰度图, glyph 掩码, ch)。只擦字本身，不膨胀。\"\"\"\n    if glyph is None:\n        glyph, _stroke, ch = split_glyph_stroke(gray)\n    else:\n        ch = _char_height(ink_binary(gray))\n    if glyph is None:\n        return None, None, None\n    out = gray.copy()\n    out[glyph > 0] = 255\n    return out, (glyph > 0).astype(np.uint8), ch\n\n\ndef clean_bond(no_glyph_gray, ch, min_width=MIN_BOND_WIDTH):\n    \"\"\"去字图 → 干净的键线（0/1）。按宽度滤掉字母残笔和碎点。\"\"\"\n    import cv2\n\n    raw = (no_glyph_gray < 200).astype(np.uint8)\n    min_area = max(6, int(MIN_AREA_FRAC * ch * ch))\n    n, lab, st, _ = cv2.connectedComponentsWithStats(raw, connectivity=8)\n    keep = np.zeros_like(raw)\n    for i in range(1, n):\n        w, h, a = int(st[i, 2]), int(st[i, 3]), int(st[i, 4])\n        if a < min_area or min(w, h) < min_width:\n            continue\n        keep[lab == i] = 1\n    return keep\n\n\ndef fit_edges(bond, ch, min_len_frac=0.6):\n    \"\"\"每条连通域 → 一条直线（PCA 拟合整段墨，不找端点）。\"\"\"\n    import cv2\n\n    n, lab, st, _ = cv2.connectedComponentsWithStats(bond.astype(np.uint8), 8)\n    min_px = max(8, int(ch * min_len_frac))\n    lines = []\n    for i in range(1, n):\n        pix = np.argwhere(lab == i)\n        if len(pix) < min_px:\n            continue\n        pts = pix[:, ::-1].astype(float)\n        mean = pts.mean(axis=0)\n        c = pts - mean\n        cov = c.T @ c / len(pts)\n        vals, vecs = np.linalg.eigh(cov)\n        d = vecs[:, int(np.argmax(vals))]\n        t = c @ d\n        lines.append({\"mean\": mean, \"dir\": d,\n                      \"t0\": float(t.min()), \"t1\": float(t.max()),\n                      \"n\": int(len(pix)), \"id\": i})\n    return lines\n\n\ndef intersections(lines, ch, H, W, extend=None):\n    \"\"\"双向延长后两两求交 → 按「距离近 + 夹角合理」合并成顶点。\n\n    返回 (clusters, raw_intersections)。\n    cluster: {\"x\", \"y\", \"pts\", \"lines\"}\n    \"\"\"\n    if extend is None:\n        extend = max(6.0, ch * EXTEND_CH)\n    pts = []\n    for i in range(len(lines)):\n        a, da = lines[i][\"mean\"], lines[i][\"dir\"]\n        ta0, ta1 = lines[i][\"t0\"] - extend, lines[i][\"t1\"] + extend\n        for j in range(i + 1, len(lines)):\n            b, db = lines[j][\"mean\"], lines[j][\"dir\"]\n            tb0, tb1 = lines[j][\"t0\"] - extend, lines[j][\"t1\"] + extend\n            M = np.column_stack([da, -db])\n            if abs(float(np.linalg.det(M))) < 1e-6:\n                continue\n            t, s = np.linalg.solve(M, b - a)\n            if not (ta0 <= t <= ta1 and tb0 <= s <= tb1):\n                continue\n            p = a + t * da\n            if not (0 <= p[0] <= W and 0 <= p[1] <= H):\n                continue\n            pts.append((float(p[0]), float(p[1]), i, j))\n\n    tol = max(4.0, MERGE_DIST_CH * ch)\n    lo, hi = MERGE_ANGLE\n    clusters = []\n    for x, y, i, j in pts:\n        placed = False\n        for c in clusters:\n            if math.hypot(x - c[\"x\"], y - c[\"y\"]) > tol:\n                continue\n            cos = float(np.clip(abs(lines[i][\"dir\"] @ lines[j][\"dir\"]), -1.0, 1.0))\n            ang = math.degrees(math.acos(cos))\n            ang = min(ang, 180.0 - ang)\n            if not (lo <= ang <= hi):\n                continue\n            c[\"pts\"].append((x, y))\n            c[\"lines\"].add(i)\n            c[\"lines\"].add(j)\n            c[\"x\"] = float(np.mean([p[0] for p in c[\"pts\"]]))\n            c[\"y\"] = float(np.mean([p[1] for p in c[\"pts\"]]))\n            placed = True\n            break\n        if not placed:\n            clusters.append({\"x\": x, \"y\": y, \"pts\": [(x, y)], \"lines\": {i, j}})\n    return clusters, pts\n\n\ndef find_vertices(gray, extend=None):\n    \"\"\"主入口：返回 dict。gray 为单通道裁图。\n\n    {\"ch\", \"no_glyph\", \"bond\", \"lines\", \"vertices\", \"raw\", \"ok\"}\n    \"\"\"\n    import cv2\n\n    no_glyph, glyph_mask, ch = remove_glyphs(gray)\n    if no_glyph is None:\n        return {\"ok\": False, \"reason\": \"墨太少\"}\n    H, W = gray.shape[:2]\n    bond = clean_bond(no_glyph, ch)\n    lines = fit_edges(bond, ch)\n    clusters, raw = intersections(lines, ch, H, W, extend=extend)\n    return {\"ok\": True, \"ch\": ch, \"no_glyph\": no_glyph,\n            \"bond\": bond, \"lines\": lines,\n            \"vertices\": clusters, \"raw\": raw,\n            \"n_vertices\": len(clusters)}\n\n\ndef draw_vertices(gray, result):\n    \"\"\"可视化：黑=键线，灰=延长线，红=顶点。\"\"\"\n    import cv2\n\n    vis = cv2.cvtColor(gray, cv2.COLOR_GRAY2BGR)\n    if not result.get(\"ok\"):\n        return vis\n    ch = result[\"ch\"]\n    vis[result[\"bond\"] > 0] = (0, 0, 0)\n    ext = max(6.0, ch * EXTEND_CH)\n    for L in result[\"lines\"]:\n        m, d = L[\"mean\"], L[\"dir\"]\n        p0 = m - (L[\"t0\"] - ext) * d\n        p1 = m + (L[\"t1\"] + ext) * d\n        cv2.line(vis, (int(p0[0]), int(p0[1])),\n                 (int(p1[0]), int(p1[1])), (150, 150, 150), 1)\n    for c in result[\"vertices\"]:\n        cv2.circle(vis, (int(c[\"x\"]), int(c[\"y\"])), 3, (0, 0, 255), -1)\n    return vis\n\n\nif __name__ == \"__main__\":\n    import sys\n\n    for name in sys.argv[1:]:\n        img = cv2.imread(name, cv2.IMREAD_GRAYSCALE)\n        if img is None:\n            print(name, \"读不了\")\n            continue\n        r = find_vertices(img)\n        if r.get(\"ok\"):\n            print(f\"{Path(name).name}: ch={r['ch']:.1f} \"\n                  f\"edges={len(r['lines'])} vertices={r['n_vertices']}\")\n        else:\n            print(f\"{Path(name).name}: {r['reason']}\")\n",
  },
  {
    path: "training/visual_notation.py",
    content: "\"\"\"视觉记法分类：在结构式裁图上用\"正文采来的字体模板\"识别字符，再判档。\n\n这是用户洞察的最终落地：\n    「正文中的字和结构式用的字体肯定是同一种，只是大小不一样。你可以去使用一下正文中的字体。」\n\n所以路径是：正文（有文本层，字符真值）→ 采字形模板 → 在结构式裁图上做模板匹配 →\n得到\"这块写的是 CH3 还是 OH\"→ 判档。不需要 OCR 训练，不需要人工标注模板。\n\n判档判据（红线：只量怎么写，不量写了什么）：\n    sub_ratio    带下标文字块 / 全部文字块   —— CH3/C6H5/CO2R 带下标；OH/NH 不带\n    has_sub_ch   含下标的块里是否含 C        —— 这才是\"显式碳缩写\"的确定证据\n    block_ratio  多字符块 / 全部块           —— 缩写 vs 单字母\n绝对数量（几个 C、几个环）一律不进判据。\n\n用法：\n    python -m training.visual_notation classify --image <png> --templates <pkl>\n    python -m training.visual_notation batch --dir <按年份目录> --templates <pkl>\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport pickle\nfrom collections import Counter\nfrom dataclasses import asdict, dataclass, field\nfrom pathlib import Path\n\nimport numpy as np\n\nfrom .notation import _ink, _read_gray, _split_lines_and_glyphs\nfrom .pdf_glyphs import match_glyph, normalize\n\nTIERS = (\"dense\", \"hybrid\", \"skeletal\")\nTIER_LABEL = {\"dense\": \"显式碳式\", \"hybrid\": \"混合式\", \"skeletal\": \"现代键线式\"}\n\n# 一个字符要被采信，相似度下限\nMIN_SCORE = 0.55\nDIGITS = set(\"0123456789\")\n\n\n@dataclass\nclass Block:\n    \"\"\"结构式里的一块文字（相邻字形聚成）。\"\"\"\n    chars: str\n    n: int\n    has_sub: bool          # 是否含\"明显更矮\"的下标字形\n    has_carbon: bool       # 是否含识别为 C 的字形\n    score: float           # 该块平均匹配分\n\n    def to_dict(self) -> dict:\n        return asdict(self)\n\n\n@dataclass\nclass ImageNotation:\n    image: str\n    tier: str = \"\"\n    confidence: float = 0.0\n    glyph_count: int = 0\n    recognized: int = 0\n    blocks: list[dict] = field(default_factory=list)\n    sub_ratio: float = 0.0\n    multi_ratio: float = 0.0\n    note: str = \"\"\n\n    def to_dict(self) -> dict:\n        d = asdict(self)\n        d[\"tier_label\"] = TIER_LABEL.get(self.tier, \"\")\n        return d\n\n\ndef _char_of(crop_gray: np.ndarray, templates: dict) -> tuple[str, float]:\n    \"\"\"把结构式里的一个小字形识别成字符。\n\n    两个关键处理，都是实测逼出来的：\n    1. **先放大再二值化**：1906 那张图的标签只有 20×27px，直接 Otsu 会把 C 的\n       开口填死，C 全被判成 O（'CO'→'OO'、'CH'→'OH'）。\n    2. **用自适应阈值而非 Otsu**：古早印刷体笔画粗，Otsu 会偏向\"全黑\"，\n       开口消失；自适应阈值按局部邻域取阈，能保住细小的开口缝隙。\n       这是区分 C 与 O 的关键——它们唯一的差别就是那条开口。\n    \"\"\"\n    import cv2\n    up = cv2.resize(crop_gray, None, fx=4.0, fy=4.0, interpolation=cv2.INTER_CUBIC)\n    up = cv2.GaussianBlur(up, (3, 3), 0)\n    # 自适应阈值：块大小随字号缩放，保证包含整条笔画\n    blk = max(11, (min(up.shape) // 3) | 1)\n    b = cv2.adaptiveThreshold(up, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C,\n                              cv2.THRESH_BINARY_INV, blk, 6)\n    # 形态学去噪（开运算去掉孤立噪点，闭运算不做——闭运算会把 C 的开口封死）\n    b = cv2.morphologyEx(b, cv2.MORPH_OPEN,\n                         cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (2, 2)))\n    if (b > 0).sum() < 12:\n        return \"\", 0.0\n    return match_glyph(b, templates)\n\n\ndef analyze_image(image: str | Path, templates: dict) -> ImageNotation:\n    gray = _read_gray(image)\n    h, w = gray.shape\n    diag = (h ** 2 + w ** 2) ** 0.5\n    ink = _ink(gray)\n    _, boxes, _, inks = _split_lines_and_glyphs(ink, h, w, diag)\n\n    if not boxes:\n        return ImageNotation(str(image), tier=\"skeletal\", confidence=0.5,\n                             note=\"无文字\")\n    med_h = float(np.median([b[3] for b in boxes])) or 1.0\n\n    # 每个字形识别成字符\n    glyphs = []\n    for (x, y, bw, bh) in boxes:\n        crop = gray[y:y + bh, x:x + bw]\n        if crop.size == 0:\n            continue\n        ch, sc = _char_of(crop, templates)\n        glyphs.append({\"ch\": ch, \"score\": sc,\n                       \"x\": x, \"y\": y, \"w\": bw, \"h\": bh,\n                       \"is_sub\": bh < 0.78 * med_h})\n    recognized = sum(1 for g in glyphs if g[\"score\"] >= MIN_SCORE)\n\n    # 聚块：同行且紧挨\n    rows: list[list[dict]] = []\n    for g in sorted(glyphs, key=lambda g: g[\"y\"] + g[\"h\"] / 2):\n        mid = g[\"y\"] + g[\"h\"] / 2\n        if rows and abs(mid - (rows[-1][0][\"y\"] + rows[-1][0][\"h\"] / 2)) <= 0.55 * med_h:\n            rows[-1].append(g)\n        else:\n            rows.append([g])\n\n    blocks: list[Block] = []\n    for row in rows:\n        row = sorted(row, key=lambda g: g[\"x\"])\n        cur = [row[0]]\n        for g in row[1:]:\n            gap = g[\"x\"] - (cur[-1][\"x\"] + cur[-1][\"w\"])\n            if gap <= 0.55 * med_h:\n                cur.append(g)\n            else:\n                blocks.append(_mk_block(cur))\n                cur = [g]\n        blocks.append(_mk_block(cur))\n\n    n_b = max(len(blocks), 1)\n    sub_n = sum(1 for b in blocks if b.has_sub)\n    multi_n = sum(1 for b in blocks if b.n >= 2)\n    sub_ratio = sub_n / n_b\n    multi_ratio = multi_n / n_b\n\n    # ---- 判档 ----\n    # 核心：带下标的块里含 C ⇒ 是 CH3/C6H5 这类显式碳缩写。\n    # 这是\"是不是显式碳\"的确定证据，不依赖\"有几个\"这样的内容量。\n    sub_with_c = sum(1 for b in blocks if b.has_sub and b.has_carbon)\n    if sub_with_c >= 2 and sub_ratio >= 0.35:\n        tier, conf = \"dense\", min(1.0, 0.55 + sub_ratio * 0.6)\n    elif sub_n >= 1 or multi_ratio >= 0.30:\n        tier, conf = \"hybrid\", min(1.0, 0.55 + sub_ratio * 0.5)\n    else:\n        tier, conf = \"skeletal\", min(1.0, 0.55 + (0.30 - multi_ratio) * 0.8)\n\n    note = \"\"\n    if recognized < 3:\n        note = f\"仅识别 {recognized} 个字符，判档不可靠\"\n\n    return ImageNotation(str(image), tier=tier, confidence=round(conf, 3),\n                         glyph_count=len(glyphs), recognized=recognized,\n                         blocks=[b.to_dict() for b in blocks[:12]],\n                         sub_ratio=round(sub_ratio, 3),\n                         multi_ratio=round(multi_ratio, 3), note=note)\n\n\ndef _mk_block(glyphs: list[dict]) -> Block:\n    chars = \"\".join(g[\"ch\"] for g in glyphs if g[\"ch\"])\n    return Block(chars=chars, n=len(glyphs),\n                 has_sub=any(g[\"is_sub\"] for g in glyphs),\n                 has_carbon=any(g[\"ch\"] == \"C\" and g[\"score\"] >= MIN_SCORE\n                                for g in glyphs),\n                 score=round(float(np.mean([g[\"score\"] for g in glyphs])), 3))\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(prog=\"csd-visual-notation\")\n    sub = ap.add_subparsers(dest=\"cmd\", required=True)\n\n    p1 = sub.add_parser(\"classify\", help=\"单图判档并打印识别出的文字块\")\n    p1.add_argument(\"--image\", required=True)\n    p1.add_argument(\"--templates\", required=True)\n\n    p2 = sub.add_parser(\"batch\", help=\"整个目录（按年份分文件夹）批量判档\")\n    p2.add_argument(\"--dir\", required=True)\n    p2.add_argument(\"--templates\", required=True)\n    p2.add_argument(\"--out\", default=\"\")\n\n    args = ap.parse_args()\n    with open(args.templates, \"rb\") as fh:\n        templates = pickle.load(fh)[\"templates\"]\n\n    if args.cmd == \"classify\":\n        r = analyze_image(args.image, templates)\n        d = r.to_dict()\n        print(f\"{Path(d['image']).name}: {d['tier']}({d['tier_label']}) \"\n              f\"conf={d['confidence']} glyphs={d['glyph_count']} \"\n              f\"recognized={d['recognized']}\")\n        print(f\"  sub_ratio={d['sub_ratio']} multi_ratio={d['multi_ratio']} {d['note']}\")\n        for b in d[\"blocks\"]:\n            print(f\"    块 '{b['chars']}' n={b['n']} sub={b['has_sub']} \"\n                  f\"carbon={b['has_carbon']} score={b['score']}\")\n        return\n\n    root = Path(args.dir)\n    import json\n    rows = []\n    for d in sorted(root.iterdir()):\n        if not d.is_dir() or not d.name.isdigit():\n            continue\n        year = int(d.name)\n        for p in sorted(d.iterdir()):\n            if p.suffix.lower() not in (\".png\", \".jpg\", \".jpeg\"):\n                continue\n            try:\n                r = analyze_image(p, templates).to_dict()\n            except Exception as exc:\n                r = {\"image\": str(p), \"error\": f\"{type(exc).__name__}: {exc}\"}\n            r[\"year\"] = year\n            rows.append(r)\n    by_year: dict[int, Counter] = {}\n    for r in rows:\n        by_year.setdefault(r[\"year\"], Counter())[r.get(\"tier\", \"error\")] += 1\n    print(f\"{'年':>5} {'n':>3} {'dense':>6} {'hybrid':>7} {'skeletal':>9}\")\n    for y in sorted(by_year):\n        c = by_year[y]\n        n = sum(c.values())\n        print(f\"{y:>5} {n:>3} {c.get('dense',0):>6} {c.get('hybrid',0):>7} \"\n              f\"{c.get('skeletal',0):>9}\")\n    if args.out:\n        Path(args.out).parent.mkdir(parents=True, exist_ok=True)\n        Path(args.out).write_text(json.dumps(rows, ensure_ascii=False, indent=2),\n                                  encoding=\"utf-8\")\n        print(\"已写\", args.out)\n\n\nif __name__ == \"__main__\":\n    main()\n",
  },
  {
    path: "training/workspace.py",
    content: "\"\"\"工作区状态管理：动态增量更新、训练轮次、留出集与交叉验证划分。\n\n用户要求：\n  - 工作区能动态更新——新文献必须补进来，不能重跑已处理的。\n  - 区分第几轮训练——每轮独立记录，可回溯。\n  - 人审剔除的图要留出作非训练集，并做交叉验证，不能全喂进去。\n\n所有状态落本地 JSON，人可读。无重型依赖。\n\n用法：\n    python -m training.workspace init --root <工作区> --pdf-dir <PDF目录>\n    python -m training.workspace sync --root <工作区>          # 增量补新文献\n    python -m training.workspace new-round --root <工作区>     # 开新一轮\n    python -m training.workspace split --root <工作区> --round 1 --folds 5\n    python -m training.workspace status --root <工作区>\n\"\"\"\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\nMANIFEST = \"workspace.json\"\nROUNDS_DIR = \"rounds\"\n\n\ndef _now() -> str:\n    return datetime.now(timezone.utc).isoformat(timespec=\"seconds\")\n\n\ndef _load(path: Path) -> dict:\n    if not path.exists():\n        raise FileNotFoundError(f\"找不到 {path}，先跑 init\")\n    return json.loads(path.read_text(encoding=\"utf-8\"))\n\n\ndef _save(data: dict, path: Path) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding=\"utf-8\")\n\n\ndef _file_id(path: Path) -> str:\n    \"\"\"用 路径+大小 做稳定 id，不读文件内容（PDF 动辄几 G，读全文太慢）。\n    内容变更但大小不变的概率极低；真要严格可换 sha256 但会很慢。\"\"\"\n    st = path.stat()\n    raw = f\"{path.name}|{st.st_size}\"\n    return hashlib.sha1(raw.encode(\"utf-8\")).hexdigest()[:12]\n\n\ndef init(root: Path, pdf_dir: Path) -> dict:\n    root = Path(root).resolve()\n    pdf_dir = Path(pdf_dir).resolve()\n    manifest = {\n        \"created_at\": _now(),\n        \"updated_at\": _now(),\n        \"pdf_dir\": str(pdf_dir),\n        \"seen\": {},       # file_id -> {name, size, added_at, round_first_seen}\n        \"rounds\": [],     # [{index, started_at, note, sample_count}]\n    }\n    path = root / MANIFEST\n    _save(manifest, path)\n    (root / ROUNDS_DIR).mkdir(parents=True, exist_ok=True)\n    print(f\"工作区已建：{path}\")\n    print(\"下一步：sync 把现有文献纳入管理\")\n    return manifest\n\n\ndef sync(root: Path) -> dict:\n    \"\"\"增量扫描 PDF 目录：新文件追加，已见过的跳过。返回新增数量。\"\"\"\n    root = Path(root).resolve()\n    path = root / MANIFEST\n    m = _load(path)\n    pdf_dir = Path(m[\"pdf_dir\"])\n    if not pdf_dir.exists():\n        raise FileNotFoundError(f\"PDF 目录不存在：{pdf_dir}\")\n\n    current_round = len(m[\"rounds\"]) or 1\n    added = 0\n    for pdf in sorted(pdf_dir.glob(\"*.pdf\")):\n        fid = _file_id(pdf)\n        if fid in m[\"seen\"]:\n            continue\n        m[\"seen\"][fid] = {\n            \"name\": pdf.name,\n            \"size\": pdf.stat().st_size,\n            \"added_at\": _now(),\n            \"round_first_seen\": current_round,\n        }\n        added += 1\n    m[\"updated_at\"] = _now()\n    _save(m, path)\n    print(f\"增量同步：新增 {added} 篇，累计 {len(m['seen'])} 篇\")\n    return {\"added\": added, \"total\": len(m[\"seen\"])}\n\n\ndef new_round(root: Path, note: str = \"\") -> dict:\n    root = Path(root).resolve()\n    path = root / MANIFEST\n    m = _load(path)\n    idx = len(m[\"rounds\"]) + 1\n    round_info = {\n        \"index\": idx,\n        \"started_at\": _now(),\n        \"note\": note,\n        \"sample_count\": 0,\n    }\n    m[\"rounds\"].append(round_info)\n    m[\"updated_at\"] = _now()\n    _save(m, path)\n    (root / ROUNDS_DIR / f\"round_{idx:03d}\").mkdir(parents=True, exist_ok=True)\n    print(f\"开启第 {idx} 轮训练 → {root / ROUNDS_DIR / f'round_{idx:03d}'}\")\n    return round_info\n\n\ndef split(root: Path, round_index: int, folds: int = 5, holdout: float = 0.2,\n          seed: int = 42) -> dict:\n    \"\"\"把某轮的人审样本划分为 训练集 / 留出集(非训练集) / 交叉验证折叠。\n\n    输入：该轮目录下 samples.json（人审样本清单，每项有 image/sha/label）\n    人审剔除的图 label=false，自动进\"非训练集\"候选池。\n    \"\"\"\n    import random\n    root = Path(root).resolve()\n    rdir = root / ROUNDS_DIR / f\"round_{round_index:03d}\"\n    src = rdir / \"samples.json\"\n    if not src.exists():\n        raise FileNotFoundError(f\"找不到 {src}；先把该轮人审样本写进来\")\n    samples = json.loads(src.read_text(encoding=\"utf-8\"))\n    if not samples:\n        raise ValueError(\"样本清单为空\")\n\n    rng = random.Random(seed)\n    items = list(samples)\n    rng.shuffle(items)\n    n_hold = max(1, int(len(items) * holdout))\n    holdout_items = items[:n_hold]\n    train_items = items[n_hold:]\n\n    # 交叉验证只在训练集内做（留出集绝不参与）\n    folds_out = []\n    for i in range(folds):\n        val = [s for j, s in enumerate(train_items) if j % folds == i]\n        folds_out.append({\"fold\": i + 1, \"val\": val})\n\n    negatives = [s for s in items if s.get(\"label\") is False]\n    out = {\n        \"round\": round_index,\n        \"split_at\": _now(),\n        \"seed\": seed,\n        \"total\": len(items),\n        \"train_count\": len(train_items),\n        \"holdout_count\": len(holdout_items),\n        \"holdout\": holdout_items,\n        \"train\": train_items,\n        \"folds\": folds_out,\n        \"negative_pool\": negatives,\n        \"note\": \"holdout 不参与训练与调参；folds 只在 train 内切分\",\n    }\n    target = rdir / \"split.json\"\n    _save(out, target)\n    print(f\"第 {round_index} 轮划分：训练 {len(train_items)} / 留出 {len(holdout_items)} / \"\n          f\"{folds} 折 / 负样本池 {len(negatives)} → {target}\")\n    return out\n\n\ndef status(root: Path) -> None:\n    root = Path(root).resolve()\n    m = _load(root / MANIFEST)\n    print(f\"PDF 目录：{m['pdf_dir']}\")\n    print(f\"已纳入文献：{len(m['seen'])} 篇（最后同步 {m['updated_at']}）\")\n    print(f\"训练轮次：{len(m['rounds'])} 轮\")\n    for r in m[\"rounds\"]:\n        split_path = root / ROUNDS_DIR / f\"round_{r['index']:03d}\" / \"split.json\"\n        mark = \"已划分\" if split_path.exists() else \"未划分\"\n        print(f\"  第 {r['index']} 轮 · {r['started_at']} · {mark} · {r.get('note') or '-'}\")\n\n\ndef main() -> None:\n    import argparse\n    ap = argparse.ArgumentParser(description=\"工作区状态管理\")\n    ap.add_argument(\"cmd\", choices=[\"init\", \"sync\", \"new-round\", \"split\", \"status\"])\n    ap.add_argument(\"--root\", required=True)\n    ap.add_argument(\"--pdf-dir\", help=\"init 用：PDF 来源目录\")\n    ap.add_argument(\"--note\", default=\"\", help=\"new-round 用\")\n    ap.add_argument(\"--round\", type=int, help=\"split 用：轮次号\")\n    ap.add_argument(\"--folds\", type=int, default=5)\n    ap.add_argument(\"--holdout\", type=float, default=0.2)\n    args = ap.parse_args()\n    root = Path(args.root).resolve()\n    if args.cmd == \"init\":\n        if not args.pdf_dir:\n            raise SystemExit(\"init 需要 --pdf-dir\")\n        init(root, Path(args.pdf_dir))\n    elif args.cmd == \"sync\":\n        sync(root)\n    elif args.cmd == \"new-round\":\n        new_round(root, args.note)\n    elif args.cmd == \"split\":\n        if not args.round:\n            raise SystemExit(\"split 需要 --round\")\n        split(root, args.round, args.folds, args.holdout)\n    else:\n        status(root)\n\n\nif __name__ == \"__main__\":\n    main()\n",
  },
  {
    path: "requirements.txt",
    content: "pymupdf>=1.26\nrequests>=2.31\nnumpy>=2.0\nopencv-python-headless>=4.10\nscipy>=1.11\nscikit-image>=0.22\nscikit-learn>=1.4\njoblib>=1.3\nPillow>=10.0\nrdkit>=2024.3\nhuggingface_hub>=0.20\nultralytics>=8.3\nnetworkx>=3.2\nrapidocr_onnxruntime>=1.4\n",
  },
  {
    path: "fetch_models.py",
    content: "\"\"\"下载 MolDet 基础权重到 models/，多源回退 + SHA256 校验。\n\n由 run-windows.bat 在装完 Python 依赖后调用。权重固定不变（不随训练更新）；\n训练产物走 assets/，与这里无关。\n\n用法：python bootstrap/fetch_models.py\n\"\"\"\nfrom __future__ import annotations\n\nimport hashlib\nimport os\nimport sys\nimport urllib.request\nfrom pathlib import Path\n\nREPO = \"UniParser/MolDet\"\nFILENAME = \"moldet_yolo11l_960_doc.pt\"\nSHA256 = \"6e1cd400e9e423a7e150296444178245244e299871a649b2de5dfce077d7c98e\"\nSIZE_MB = 49\n\n\ndef _sha(path: Path) -> str:\n    h = hashlib.sha256()\n    with path.open(\"rb\") as f:\n        for block in iter(lambda: f.read(1 << 20), b\"\"):\n            h.update(block)\n    return h.hexdigest()\n\n\ndef _try_direct(url: str, target: Path) -> bool:\n    \"\"\"用 urllib 直连国内镜像下载，主动清掉代理变量（避免代理软件把 HF 请求转成 502）。\"\"\"\n    tmp = target.with_suffix(\".download\")\n    try:\n        print(f\"  直连下载 {url.split('/')[2]} ...\", flush=True)\n        # 国内镜像应直连；有些用户开着代理软件会把请求转发到国外导致失败，这里清掉\n        saved = {k: os.environ.pop(k, None) for k in\n                 (\"http_proxy\", \"https_proxy\", \"HTTP_PROXY\", \"HTTPS_PROXY\", \"ALL_PROXY\", \"all_proxy\")}\n        try:\n            proxy_handler = urllib.request.ProxyHandler({})\n            opener = urllib.request.build_opener(proxy_handler)\n            req = urllib.request.Request(url, headers={\"User-Agent\": \"Mozilla/5.0\"})\n            with opener.open(req, timeout=60) as resp, tmp.open(\"wb\") as f:\n                while True:\n                    chunk = resp.read(1 << 20)\n                    if not chunk:\n                        break\n                    f.write(chunk)\n        finally:\n            for k, v in saved.items():\n                if v is not None:\n                    os.environ[k] = v\n        got = _sha(tmp)\n        if got != SHA256:\n            print(f\"  SHA 不符：{got[:16]}...\")\n            tmp.unlink(missing_ok=True)\n            return False\n        tmp.replace(target)\n        print(f\"  校验通过：{target.name}\")\n        return True\n    except Exception as exc:\n        print(f\"  直连异常：{type(exc).__name__}: {str(exc)[:120]}\")\n        tmp.unlink(missing_ok=True)\n        return False\n\n\ndef _try_hub(endpoint: str | None, target: Path) -> bool:\n    \"\"\"用 huggingface_hub 从指定端点下载；成功且校验通过返回 True。\"\"\"\n    try:\n        from huggingface_hub import hf_hub_download\n        if endpoint:\n            os.environ[\"HF_ENDPOINT\"] = endpoint\n        print(f\"  尝试 {endpoint or 'huggingface.co'} ...\", flush=True)\n        p = hf_hub_download(repo_id=REPO, filename=FILENAME, local_dir=str(target.parent))\n        got = _sha(Path(p))\n        if got != SHA256:\n            print(f\"  SHA 不符：{got[:16]}...，换下一个源\")\n            return False\n        if Path(p).name != FILENAME:\n            Path(p).rename(target)\n        print(f\"  校验通过：{target.name} ({SIZE_MB} MB)\")\n        return True\n    except Exception as exc:\n        print(f\"  失败：{type(exc).__name__}: {str(exc)[:160]}\")\n        return False\n\n\ndef main() -> None:\n    # 基于当前工作目录（启动器已 cd 到 BASE=requirements 所在目录），\n    # 不用 __file__——开发时脚本在 bootstrap/、引导时在根目录，__file__ 会算错位置。\n    target = Path.cwd() / \"models\" / FILENAME\n    target.parent.mkdir(parents=True, exist_ok=True)\n    if target.exists() and _sha(target) == SHA256:\n        print(f\"MolDet 权重已就绪：{target}\")\n        return\n    if target.exists():\n        print(\"已有权重校验失败，重新下载\")\n        target.unlink()\n\n    print(f\"首次准备 MolDet 分子检测权重（约 {SIZE_MB} MB）...\")\n    # ModelScope（阿里魔搭，国内直连最稳）优先，其次 hf-mirror，最后 HF\n    urls = [\n        f\"https://www.modelscope.cn/models/{REPO}/resolve/master/{FILENAME}\",\n        f\"https://hf-mirror.com/{REPO}/resolve/main/{FILENAME}\",\n        f\"https://huggingface.co/{REPO}/resolve/main/{FILENAME}\",\n    ]\n    for url in urls:\n        if _try_direct(url, target):\n            break\n    else:\n        for endpoint in (\"https://hf-mirror.com\", None):\n            if _try_hub(endpoint, target):\n                break\n        else:\n            print(\"[ERROR] 所有源都失败。检查网络或手动下载到 models/：\", file=sys.stderr)\n            print(f\"  {FILENAME}  SHA256={SHA256}\", file=sys.stderr)\n            sys.exit(1)\n\n\nif __name__ == \"__main__\":\n    main()\n",
  },
  {
    path: "run-windows.bat",
    content: "@echo off\r\nsetlocal enabledelayedexpansion\r\nrem This script may live in <root>\\bootstrap (dev) or directly in <root> (guided deploy).\r\nrem Locate the folder that actually contains requirements.txt and make it the base.\r\nset \"BASE=%~dp0\"\r\n:findbase\r\nif exist \"%BASE%requirements.txt\" goto base_ok\r\nfor %%P in (\"%BASE%..\\\") do set \"UP=%%~fP\"\r\nif /i \"%UP%\"==\"%BASE:~0,-1%\" goto base_missing\r\nset \"BASE=%UP%\"\r\ngoto findbase\r\n:base_ok\r\ncd /d \"%BASE%\"\r\nrem Miniconda installer rejects non-ASCII install paths (e.g. Chinese folder names).\r\nrem Use exit code only (no output parsing) to avoid quoting pitfalls.\r\nset \"CSD_CUR=%CD%\"\r\npowershell -NoProfile -Command \"if ($env:CSD_CUR -match '[\\u0080-\\uFFFF]') { exit 1 } else { exit 0 }\"\r\nif errorlevel 1 goto non_ascii_path\r\nrem Keep everything inside this folder: no pip cache, no __pycache__, no system writes.\r\nset \"PYTHONDONTWRITEBYTECODE=1\"\r\nset \"PIP_NO_CACHE_DIR=1\"\r\nset \"PYTHONPYCACHEPREFIX=%CD%\\.runtime\\pycache\"\r\n\r\necho ============================================\r\necho  CSD local backend - first run sets up everything\r\necho  ISOLATED: Python and all packages live in .runtime\\\r\necho            Nothing is installed system-wide. Delete the folder to remove all.\r\necho  Backend: http://127.0.0.1:8765\r\necho ============================================\r\n\r\nset \"PY=.runtime\\python.exe\"\r\nset \"MC=Miniconda3-py312_26.9.4-1-Windows-x86_64.exe\"\r\n\r\nif exist \"%PY%\" goto have_runtime\r\n\r\necho.\r\necho [1/5] Preparing a private Python runtime (one time, about 90 MB)\r\necho        From Chinese mirrors - no VPN needed. You do NOT need Python installed.\r\nif not exist \".runtime\" mkdir \".runtime\"\r\n\r\nwhere curl >nul 2>nul\r\nif errorlevel 1 goto no_curl\r\necho        Downloading from TUNA mirror ...\r\ncurl -fL --retry 2 -o \"%MC%\" \"https://mirrors.tuna.tsinghua.edu.cn/anaconda/miniconda/%MC%\"\r\nif not errorlevel 1 goto unpack\r\nif exist \"%MC%\" del /q \"%MC%\"\r\necho        TUNA failed, trying Huawei Cloud ...\r\ncurl -fL --retry 2 -o \"%MC%\" \"https://mirrors.huaweicloud.com/anaconda/miniconda/%MC%\"\r\nif not errorlevel 1 goto unpack\r\nif exist \"%MC%\" del /q \"%MC%\"\r\ngoto download_failed\r\n\r\n:unpack\r\necho [2/5] Installing Python into .runtime (silent, nothing system-wide) ...\r\nrem JustMe + RegisterPython=0 + no PATH: nothing is written system-wide. /D must be last, no quotes.\r\n\"%MC%\" /InstallationType=JustMe /RegisterPython=0 /S /D=%CD%\\.runtime\r\nif errorlevel 1 goto unpack_failed\r\nif exist \"%MC%\" del /q \"%MC%\"\r\n\r\n:have_runtime\r\nif not exist \"%PY%\" goto runtime_missing\r\n\r\n:install_deps\r\necho [3/5] Installing components into the private runtime (first run only)\r\necho        All packages go into .runtime - nothing is written to the system Python.\r\nset \"PIPFLAGS=--disable-pip-version-check --no-warn-script-location --no-cache-dir --timeout 20 --retries 2\"\r\nrem Try several indexes; any one succeeding is enough. Official last.\r\ncall :try_pip \"https://pypi.tuna.tsinghua.edu.cn/simple\"\r\nif not errorlevel 1 goto check_native\r\ncall :try_pip \"https://mirrors.aliyun.com/pypi/simple/\"\r\nif not errorlevel 1 goto check_native\r\ncall :try_pip \"https://pypi.doubanio.com/simple/\"\r\nif not errorlevel 1 goto check_native\r\ncall :try_pip \"\"\r\nif errorlevel 1 goto pip_failed\r\ngoto check_native\r\n\r\n:try_pip\r\necho        pip index: %~1\r\nif \"%~1\"==\"\" (\r\n  \"%PY%\" -m pip install %PIPFLAGS% -r requirements.txt\r\n) else (\r\n  \"%PY%\" -m pip install %PIPFLAGS% -r requirements.txt -i %~1\r\n)\r\nexit /b %errorlevel%\r\n\r\n:check_native\r\necho [4/5] Checking native deps ...\r\n\"%PY%\" -c \"import cv2, numpy, pymupdf; print('core ok')\"\r\nif errorlevel 1 goto native_failed\r\n\r\necho [5/5] Preparing MolDet model weight (first run downloads ~50 MB) ...\r\nif exist \"fetch_models.py\" goto fetch_here\r\nif exist \"bootstrap\\fetch_models.py\" goto fetch_sub\r\necho [WARN] fetch_models.py not found; skipping MolDet weight check.\r\ngoto after_fetch\r\n:fetch_here\r\n\"%PY%\" fetch_models.py\r\nif errorlevel 1 goto model_failed\r\ngoto after_fetch\r\n:fetch_sub\r\n\"%PY%\" bootstrap\\fetch_models.py\r\nif errorlevel 1 goto model_failed\r\n:after_fetch\r\n\r\nif defined CSD_DATA_DIR (\r\n  echo Data dir: %CSD_DATA_DIR%\r\n) else (\r\n  echo Data dir: ^(default^) ./data\r\n)\r\n\r\necho.\r\necho Starting backend ... Keep this window open. Close it to stop the server.\r\necho.\r\n\"%PY%\" -m backend.server\r\nif errorlevel 86 goto restart\r\nif errorlevel 1 goto backend_failed\r\nexit /b 0\r\n\r\n:restart\r\necho Backend requested restart ...\r\nstart \"\" \"%~dp0start-windows.bat\"\r\nexit /b 0\r\n\r\n:base_missing\r\necho [ERROR] requirements.txt not found above this folder. Put the launcher in the folder with requirements.txt.\r\npause\r\nexit /b 1\r\n:non_ascii_path\r\necho [ERROR] The folder path contains non-ASCII characters (e.g. Chinese).\r\necho         The Python installer cannot install into such a path.\r\necho.\r\necho         Current path: %CD%\r\necho         Please rename the folder to use English letters only (e.g. CSD),\r\necho         or move it to an English path like C:\\CSD, then run again.\r\npause\r\nexit /b 1\r\n:download_failed\r\necho [ERROR] Cannot download Python runtime from TUNA or Huawei Cloud mirrors.\r\necho         Check your network connection to Chinese mirrors.\r\npause\r\nexit /b 1\r\n:no_curl\r\necho [ERROR] curl.exe not found. Need Windows 10 1803+ (curl is built in).\r\npause\r\nexit /b 1\r\n:unpack_failed\r\necho [ERROR] Failed to unpack Python runtime.\r\npause\r\nexit /b 1\r\n:runtime_missing\r\necho [ERROR] Python runtime missing at .runtime\\python.exe.\r\npause\r\nexit /b 1\r\n:pip_failed\r\necho [ERROR] pip install failed. Check network, or use a different mirror.\r\npause\r\nexit /b 1\r\n:native_failed\r\necho [ERROR] Core deps failed to import. Try: pip install opencv-python pymupdf\r\npause\r\nexit /b 1\r\n:model_failed\r\necho [ERROR] MolDet weight download failed. See message above.\r\npause\r\nexit /b 1\r\n:backend_failed\r\necho [ERROR] Backend exited with an error.\r\npause\r\nexit /b 1\r\n",
    promote: true,
  },
  {
    path: "start-windows.bat",
    content: "@echo off\r\nsetlocal\r\ncd /d \"%~dp0\"\r\nif not exist \"run-windows.bat.new\" goto run\r\nif exist \"run-windows.bat\" del /q \"run-windows.bat\"\r\nmove /y \"run-windows.bat.new\" \"run-windows.bat\" >nul 2>nul\r\n:run\r\nif not exist \"run-windows.bat\" goto missing\r\ncall \"run-windows.bat\"\r\nexit /b %errorlevel%\r\n:missing\r\necho [ERROR] run-windows.bat is missing from this folder.\r\npause\r\nexit /b 1\r\n",
    launcher: true,
  },
  {
    path: "uninstall-windows.bat",
    content: "@echo off\r\nsetlocal\r\ncd /d \"%~dp0..\"\r\n\r\necho ============================================\r\necho  CSD - remove ALL local files\r\necho  This deletes: .runtime, pycache, data, training outputs\r\necho  Nothing outside this folder was ever written by CSD.\r\necho ============================================\r\necho.\r\n\r\nset /p \"CONFIRM=Type YES to delete everything in this folder's runtime/data: \"\r\nif /i not \"%CONFIRM%\"==\"YES\" (\r\n  echo Cancelled. Nothing removed.\r\n  pause\r\n  exit /b 0\r\n)\r\n\r\nif exist \".runtime\" (\r\n  echo Removing .runtime ...\r\n  rmdir /s /q \".runtime\"\r\n)\r\nif exist \"data\" (\r\n  echo Removing data ...\r\n  rmdir /s /q \"data\"\r\n)\r\nif exist \"training\" (\r\n  echo Removing training outputs ...\r\n  rmdir /s /q \"training\\01-collect\" 2>nul\r\n  rmdir /s /q \"training\\02-topo\" 2>nul\r\n  rmdir /s /q \"training\\03-style\" 2>nul\r\n  rmdir /s /q \"training\\04-render\" 2>nul\r\n  rmdir /s /q \"training\\05-match\" 2>nul\r\n  rmdir /s /q \"training\\models\" 2>nul\r\n  rmdir /s /q \"training\\templates\" 2>nul\r\n  rmdir /s /q \"training\\render_cache\" 2>nul\r\n)\r\necho.\r\necho Done. All CSD runtime and data removed.\r\necho The source code and bootstrap scripts remain (that is your copy of the app).\r\npause\r\nexit /b 0\r\n",
  }
